// 语法知识点讲解（生成文件，勿手改）：来源 miniprogram/content/deep-*.js
// 每条包含：key、label、definition（一句话定义）、identify（怎么识别）、
// usage（怎么用）、translate（怎么译）、trap（易错正误对比）、examples（例句）
module.exports = [
{"key":"subject-verb-agreement","label":"主谓一致（the number of / each / neither…nor）","definition":"主谓一致指谓语单复数跟真正的主语保持一致，不看离它最近的名词。","identify":"先找到主语中心词，再看 the number of、each、neither…nor 这类结构：数量短语看中心词，就近结构看最近的主语。","usage":"三步：一、划掉介词短语找中心词；二、the number of 作主语用单数，a number of 用复数；三、each、either 用单数，neither…nor 连接主语时就近一致。","translate":"中文没有数的变化；但要分清 the number of 是“……的数量”，a number of 是“许多”。","trap":{"wrong":"The number of students who attend the lecture are increasing.","right":"The number of students who attend the lecture is increasing.","note":"主语中心词是 the number，不是 students，谓语要用单数 is。"},"examples":[{"en":"The number of applicants has doubled over the past five years.","zh":"过去五年里，申请人数翻了一番。"},{"en":"Neither the manager nor the employees were informed of the change.","zh":"经理和员工都没有被告知这项变动。"}],"understanding":"主谓一致指谓语单复数跟真正的主语保持一致，不看离它最近的名词。","translation":"中文没有数的变化；但要分清 the number of 是“……的数量”，a number of 是“许多”。"},
{"key":"nominalization","label":"名词化结构（the implementation of …）","definition":"名词化是把动词或形容词变成名词来表达，使句子更正式、信息更密集。","identify":"看到 the implementation of 这类“the+名词+of”，后面还跟着动作对象，就是名词化。","usage":"公式：the+动作名词+of+宾语，如 the implementation of the policy。原主语可用 by 引出。多个 of 叠加时，先找中心词，再还原成动词句理解。","translate":"中文常还原成动词：“实施这项政策”，不要机械译成“……的实施”，否则句子又长又绕。","trap":{"wrong":"The company announced the implement of the new policy.","right":"The company announced the implementation of the new policy.","note":"implement 是动词，名词化要用 implementation，不能直接加 of。"},"examples":[{"en":"The rapid development of artificial intelligence has changed the job market.","zh":"人工智能的快速发展改变了就业市场。"},{"en":"The successful application of the theory depends on accurate data.","zh":"这一理论能否成功应用取决于数据是否准确。"}],"understanding":"名词化是把动词或形容词变成名词来表达，使句子更正式、信息更密集。","translation":"中文常还原成动词：“实施这项政策”，不要机械译成“……的实施”，否则句子又长又绕。"},
{"key":"reflexive-use","label":"反身代词（主语和宾语同指）","definition":"反身代词指回句子主语，表示动作的承受者就是发出者，如 myself、itself。","identify":"句中出现 myself、yourself、himself、itself 等，且它指的人和主语是同一个，就是反身代词。","usage":"判断法：把反身代词换回主语，意思不变就是同指。它可作宾语、同位语，也用于固定搭配：enjoy oneself 玩得开心，in itself 本身，by oneself 独自。主语是复数时，反身代词也用复数。","translate":"不要一律译“自己”：enjoy oneself 译“玩得开心”，in itself 译“本身”。","trap":{"wrong":"The students taught himself to play the guitar.","right":"The students taught themselves to play the guitar.","note":"主语是复数 students，反身代词要用 themselves，不能用 himself。"},"examples":[{"en":"She found herself unable to answer the question.","zh":"她发现自己回答不了这个问题。"},{"en":"The children behaved themselves during the long journey.","zh":"孩子们在漫长的旅途中很守规矩。"}],"understanding":"反身代词指回句子主语，表示动作的承受者就是发出者，如 myself、itself。","translation":"不要一律译“自己”：enjoy oneself 译“玩得开心”，in itself 译“本身”。"},
{"key":"by-oneself","label":"by + 反身代词 / by oneself","definition":"by+反身代词表示“独自、靠自己、不需要别人帮助”，by itself 还可表示“自动地”。","identify":"看到 by oneself、by myself、by themselves 放在动词后，说明动作是主语独自完成的。","usage":"结构是 by+反身代词，反身代词必须和主语一致。它回答 how，相当于 alone 或 without help。注意它不是“被自己”；被动语态才用 by+名词表示动作发出者。by itself 指物时可译“自动地”。","translate":"译成“独自、靠自己、无人帮助”；指物时 by itself 可译“自动地”或“本身”。","trap":{"wrong":"He finished the project by him.","right":"He finished the project by himself.","note":"by 表示“独自”时必须接反身代词，不能用人称代词宾格 him。"},"examples":[{"en":"She learned to cook by herself after moving abroad.","zh":"出国后她学着自己做饭。"},{"en":"The machine will shut down by itself if it overheats.","zh":"如果过热，这台机器会自动关机。"}],"understanding":"by+反身代词表示“独自、靠自己、不需要别人帮助”，by itself 还可表示“自动地”。","translation":"译成“独自、靠自己、无人帮助”；指物时 by itself 可译“自动地”或“本身”。"},
{"key":"formal-it","label":"it 作形式主语 / 形式宾语","definition":"it 作形式主语或形式宾语时不指任何东西，只占位置，真正内容在后面。","identify":"句首 It is+形容词+to do，或 make/find/think+it+形容词+to do，这里 it 都是形式主语或宾语。","usage":"划掉 it，把后面的 to do 或 that 从句搬到 it 的位置，句子仍成立。常见：It is important to do…；make it possible to do…；find it hard to do…。","translate":"中文把真正内容提前：“做某事很重要”“使……成为可能”，不要译“它是……”。","trap":{"wrong":"Is important to protect personal data.","right":"It is important to protect personal data.","note":"英语句子必须有主语，用 it 占位，真正的主语是后面的不定式。"},"examples":[{"en":"It is difficult to predict how the market will react.","zh":"很难预测市场会如何反应。"},{"en":"The new policy makes it easier for small firms to borrow money.","zh":"新政策让小公司更容易借到钱。"}],"understanding":"it 作形式主语或形式宾语时不指任何东西，只占位置，真正内容在后面。","translation":"中文把真正内容提前：“做某事很重要”“使……成为可能”，不要译“它是……”。"},
{"key":"it-takes","label":"It takes sb + 时间 + to do","definition":"It takes sb+时间+to do 表示“做某事花了某人多少时间”，it 是形式主语。","identify":"看到 It takes/took/will take，后面出现人、时间段，再跟 to do，就是这一句型。","usage":"公式：It takes+人+时间+to do。人可省略：It takes time to build trust。时态由 takes 变化。问句 How long does it take to do…？注意 spend 的主语必须是人。","translate":"译成“做某事需要（某人）多少时间”或“某人花了多少时间做某事”。","trap":{"wrong":"It takes me two hours finish the report.","right":"It takes me two hours to finish the report.","note":"takes 后面的动作要用不定式 to do，不能直接接动词原形。"},"examples":[{"en":"It took the team six months to complete the experiment.","zh":"团队花了六个月完成这项实验。"},{"en":"It takes patience to learn a foreign language well.","zh":"学好一门外语需要耐心。"}],"understanding":"It takes sb+时间+to do 表示“做某事花了某人多少时间”，it 是形式主语。","translation":"译成“做某事需要（某人）多少时间”或“某人花了多少时间做某事”。"},
{"key":"it-no-use","label":"It is no use / There is no point in doing","definition":"两个句型都表示“做某事没有用、没有意义”，后面都接动名词 doing。","identify":"句首是 It is no use/no good，或 There is no point in，后面直接跟动词-ing。","usage":"固定结构：It is no use/no good+doing；There is no point in+doing。后面必须用动名词，不能用 to do。前者更口语，后者更强调“没有意义”。","translate":"译成“做……没有用”“做……没有意义”，不要按字面译“没有使用”。","trap":{"wrong":"It is no use to argue with him.","right":"It is no use arguing with him.","note":"no use 后面固定接动名词 doing，不能换成不定式 to do，这是固定搭配。"},"examples":[{"en":"It is no use complaining about problems you cannot change.","zh":"抱怨你改变不了的问题没有用。"},{"en":"There is no point in buying a car you rarely drive.","zh":"买一辆很少开的车没有意义。"}],"understanding":"两个句型都表示“做某事没有用、没有意义”，后面都接动名词 doing。","translation":"译成“做……没有用”“做……没有意义”，不要按字面译“没有使用”。"},
{"key":"it-is-said","label":"It is said / believed / estimated that …","definition":"It is said/believed/estimated that… 用 it 引出传言或估计。","identify":"句首出现 It is said/reported/believed/estimated，后面紧跟 that 从句，就是这类结构。","usage":"公式：It is+过去分词+that+完整句子。可转换成“主语+is said to do”：It is said that he lives abroad=He is said to live abroad。学术写作中用它使语气客观。","translate":"译成“据说、据报道、人们认为、据估计”，不要译成“它被说”。","trap":{"wrong":"It is said that he is living abroad for ten years.","right":"It is said that he has lived abroad for ten years.","note":"for ten years 表示持续到现在，从句要用现在完成时 has lived。"},"examples":[{"en":"It is estimated that the project will cost two billion dollars.","zh":"据估计，这个项目将耗资二十亿美元。"},{"en":"It is widely believed that sleep improves memory and learning.","zh":"人们普遍认为睡眠能改善记忆和学习。"}],"understanding":"It is said/believed/estimated that… 用 it 引出传言或估计。","translation":"译成“据说、据报道、人们认为、据估计”，不要译成“它被说”。"},
{"key":"articles","label":"冠词（a / an / the 与零冠词）","definition":"冠词放在名词前，a/an 表示“一个、某一类”，the 表示“特定的那个”，零冠词就是名词前什么也不加。","identify":"单数可数名词前通常必须有冠词；首次提到用 a/an，再次提到用 the；世上唯一或上下文明确用 the；复数泛指、不可数泛指、专有名词和固定短语常不用冠词。","usage":"三步判断：①名词是否可数单数，是就必须带冠词；②听者能否确定是哪一个，能确定就用 the，不能确定就用 a/an；③a/an 看读音不看字母，如 an hour、a university。固定短语整块记：in the morning、at night、go to school、play the piano。另外，a/an 只用于单数可数名词，复数和不可数名词泛指时用零冠词。","translate":"a/an 常译“一个”或干脆不译；the 译“这个/那个”或不译；复数泛指不译。中文没有冠词，不要见名词就硬加“一个”。","trap":{"wrong":"He is a honest man.","right":"He is an honest man.","note":"honest 的 h 不发音，开头实际是元音音素，所以用 an；a/an 看读音，不看拼写字母，元音音素前用 an。"},"examples":[{"en":"The scientist who discovered the vaccine won a major prize.","zh":"发现这种疫苗的科学家获得了一项大奖。"},{"en":"Children need plenty of sleep to grow well.","zh":"孩子需要充足的睡眠才能长得好。"},{"en":"She plays the violin in a local orchestra.","zh":"她在一个本地乐团拉小提琴。"}],"understanding":"冠词放在名词前，a/an 表示“一个、某一类”，the 表示“特定的那个”，零冠词就是名词前什么也不加。","translation":"a/an 常译“一个”或干脆不译；the 译“这个/那个”或不译；复数泛指不译。中文没有冠词，不要见名词就硬加“一个”。"},
{"key":"prepositions","label":"介词（时间、地点、方式与固定搭配）","definition":"介词是句子里的“关系词”，把名词和别的成分连起来，表示时间、地点、方式、原因等关系。","identify":"介词后面一定跟名词、代词或动名词，不跟句子；看到 in/on/at/for/by/with 先判断它管的是时间、地点还是方式，再看是不是固定搭配。","usage":"时间：in 年、月、季节，on 具体某天，at 时刻；地点：in 大范围，on 表面或街道，at 具体点；方式：by 交通工具或手段，with 工具，in 语言或材料。介词后接动词一律用 doing，如 look forward to hearing。固定搭配整块记，不能照中文逐字换；介词短语还能作定语和状语，位置不同，修饰的对象也不同。","translate":"介词常不单独译，融进动词或方位词里：in the box 译“在盒子里”，by bus 译“坐公交”，with a pen 译“用笔”，不要逐字对译。","trap":{"wrong":"I am looking forward to hear from you.","right":"I am looking forward to hearing from you.","note":"look forward to 里的 to 是介词，不是不定式符号，后面必须接动名词 hearing，这一点最容易按中文习惯写错。"},"examples":[{"en":"The meeting has been put off until next Tuesday.","zh":"会议被推迟到下周二。"},{"en":"She solved the problem by asking her colleagues for help.","zh":"她通过向同事求助解决了这个问题。"},{"en":"They arrived at the airport two hours before the flight.","zh":"他们在航班起飞前两小时到达了机场。"}],"understanding":"介词是句子里的“关系词”，把名词和别的成分连起来，表示时间、地点、方式、原因等关系。","translation":"介词常不单独译，融进动词或方位词里：in the box 译“在盒子里”，by bus 译“坐公交”，with a pen 译“用笔”，不要逐字对译。"},
{"key":"pronoun-types","label":"代词细类（人称 / 物主 / 指示 / 不定）","definition":"代词用来代替名词或名词短语，按功能分成人称、物主、指示、不定等几类，各有各的位置和搭配。","identify":"人称代词分主格和宾格；物主代词分形容词性和名词性；指示代词是 this/that/these/those；不定代词是 some/any/few/little/both/either/neither/all/none 这一类，要按数量和可数性区分。","usage":"some 多用于肯定句，any 多用于否定句和疑问句；few/a few 修饰可数名词，little/a little 修饰不可数，带 a 表示“有一些”，不带 a 表示“几乎没有”；both/either/neither 管两者，all/none 管三者及以上，either 是“两者之一”，neither 是“两者都不”，none 是“一个也没有”。修饰可数名词用 few，修饰不可数名词用 little，两类不能混用。","translate":"主格和宾格都译“我/他”，名词性物主代词译“我的（东西）”；few 译“很少”，a few 译“几个”，neither 译“两者都不”，none 译“一个也没有”。","trap":{"wrong":"Neither of the two answers are correct.","right":"Neither of the two answers is correct.","note":"neither of 作主语时谓语用单数 is；neither 本身已含否定，句中不能再加 not，否则就成了双重否定。"},"examples":[{"en":"Some of the students had read the novel, but none of them could explain it.","zh":"有些学生读过这本小说，但没有一个人能解释它。"},{"en":"Either of these two routes will take you to the station.","zh":"这两条路线中的任何一条都能带你到车站。"},{"en":"This is my notebook; yours is on the desk.","zh":"这是我的笔记本，你的在桌上。"}],"understanding":"代词用来代替名词或名词短语，按功能分成人称、物主、指示、不定等几类，各有各的位置和搭配。","translation":"主格和宾格都译“我/他”，名词性物主代词译“我的（东西）”；few 译“很少”，a few 译“几个”，neither 译“两者都不”，none 译“一个也没有”。"},
{"key":"perfect-tense","label":"完成时与完成进行时（have done / have been doing）","definition":"完成时用 have/has/had+过去分词，表示到某时间点已完成或持续；完成进行时强调持续。","identify":"看到 have/has/had+过去分词，或 have been doing，再找 since、for、by the time。","usage":"先看助动词：have/has 是现在完成，had 是过去完成。现在完成强调“到现在为止”，配 since、for、so far；过去完成强调“在过去某点之前”，配 by then、before。have been doing 强调持续。","translate":"译成“已经……”“一直……”。过去完成常译“在……之前就已经……”。","trap":{"wrong":"I have seen him yesterday.","right":"I saw him yesterday.","note":"yesterday 是明确的过去时间，不能用现在完成时，要用一般过去时。"},"examples":[{"en":"She has worked in the same company for over ten years.","zh":"她在同一家公司工作了十多年。"},{"en":"By the time we arrived, the lecture had already ended.","zh":"我们到达时，讲座已经结束了。"},{"en":"It has been raining heavily since early this morning.","zh":"从清早开始就一直在下大雨。"}],"understanding":"完成时用 have/has/had+过去分词，表示到某时间点已完成或持续；完成进行时强调持续。","translation":"译成“已经……”“一直……”。过去完成常译“在……之前就已经……”。"},
{"key":"progressive-tense","label":"进行时（is / are / was / were + doing）","definition":"进行时由 be+动词-ing 构成，表示某时刻正在发生或现阶段持续的动作。","identify":"看到 am/is/are/was/were+doing，就是进行时；常和 now、at the moment、when、while 连用。","usage":"公式：be+doing，be 的时态决定时间：is doing 现在进行，was doing 过去进行。表示状态的动词（know、own）一般不用进行时。过去进行常和一般过去时搭配：was doing…when did…。","translate":"译成“正在……”“不断……”。过去进行常译“当时正在……”，when 从句译“这时……”。","trap":{"wrong":"She is knowing the answer.","right":"She knows the answer.","note":"know 表示状态而不是动作，一般不用进行时，应该用一般现在时 knows。"},"examples":[{"en":"More people are working from home than ever before.","zh":"现在居家办公的人比以往任何时候都多。"},{"en":"I was walking to the station when I met an old friend.","zh":"我正走去车站时遇到了一位老朋友。"}],"understanding":"进行时由 be+动词-ing 构成，表示某时刻正在发生或现阶段持续的动作。","translation":"译成“正在……”“不断……”。过去进行常译“当时正在……”，when 从句译“这时……”。"},
{"key":"future-tense","label":"将来时与将来进行/完成（will do / will be doing / will have done）","definition":"将来时用 will+动词原形；be going to 表计划；will be doing 表将来。","identify":"看到 will、be going to、will be doing，再找 tomorrow、next year、by 2030。","usage":"will do 表单纯将来或临时决定；be going to 表计划或明显迹象；will be doing 表将来某时正在进行；will have done 表到将来某时已完成，常配 by+将来时间。will 后永远接原形。","translate":"译成“将……”“会……”“打算……”。will have done 译“到……时已经……”。","trap":{"wrong":"He will goes to Beijing next week.","right":"He will go to Beijing next week.","note":"will 是情态助动词，后面必须接动词原形，不能加 -es。"},"examples":[{"en":"The new rules will take effect at the beginning of next year.","zh":"新规定将于明年年初生效。"},{"en":"By 2030, the city will have built three new subway lines.","zh":"到 2030 年，这座城市将建成三条新地铁线。"}],"understanding":"将来时用 will+动词原形；be going to 表计划；will be doing 表将来。","translation":"译成“将……”“会……”“打算……”。will have done 译“到……时已经……”。"},
{"key":"used-to","label":"used to do / be used to doing / be used to do 三组易混","definition":"used to 过去常常；be used to doing 习惯；be used to do 被动。","identify":"先看 used 前有没有 be：无 be 接原形是“过去常常”；有 be 接 doing 是“习惯于”；接 to do 是“被用来”。","usage":"三组分清：used to+原形，只指过去的习惯；be used to+名词/doing，to 是介词，表示习惯于；be used to do 是被动，表示被用来做。否定和疑问用 did：didn't use to。","translate":"分别译“过去常常”“习惯于”“被用来做”，不要把 be used to doing 译成“被用来做”。","trap":{"wrong":"She is used to get up early.","right":"She is used to getting up early.","note":"be used to 表示习惯于时，to 是介词，后面要接动名词 getting。"},"examples":[{"en":"He used to walk to school when he lived in the village.","zh":"他住在村里时常常步行上学。"},{"en":"This software is used to analyze large amounts of data.","zh":"这款软件被用来分析大量数据。"}],"understanding":"used to 过去常常；be used to doing 习惯；be used to do 被动。","translation":"分别译“过去常常”“习惯于”“被用来做”，不要把 be used to doing 译成“被用来做”。"},
{"key":"be-to-do","label":"be to do（计划 / 安排 / 命令 / 注定）","definition":"be to do 表示按计划或安排将要发生的事，也可表示命令、要求或注定。","identify":"看到 am/is/are/was/were+to do，而不是 will，就是 be to do，多见于通知、规定和新闻。","usage":"四种含义：计划安排（is to be held）、命令要求（are to report）、注定（was never to see）、禁止（are not to smoke）。它比 will 正式，语气更确定。","translate":"译成“定于……”“将要……”“必须……”“注定……”，按上下文选，不要一律译“是去……”。","trap":{"wrong":"The meeting is to holding next Monday.","right":"The meeting is to be held next Monday.","note":"be to 后面必须接动词原形；会议是被举行的，所以用被动 to be held。"},"examples":[{"en":"The president is to visit three European countries next month.","zh":"总统定于下月访问三个欧洲国家。"},{"en":"You are not to leave the room without permission.","zh":"未经允许你不得离开这个房间。"}],"understanding":"be to do 表示按计划或安排将要发生的事，也可表示命令、要求或注定。","translation":"译成“定于……”“将要……”“必须……”“注定……”，按上下文选，不要一律译“是去……”。"},
{"key":"passive-basic","label":"一般被动语态（be + 过去分词）","definition":"被动语态由 be+过去分词构成，主语是动作的承受者，不是发出者。","identify":"看谓语是不是 be+过去分词，再问一句动作是谁做的：不是主语做的，就是被动语态。","usage":"公式：be+过去分词，be 负责时态和单复数：is done、was done、will be done。动作发出者用 by 引出，不重要可省略。be interested in 这类是状态，不强调动作。","translate":"中文可译“被……”，但更常转成主动句或无主句，“广泛使用”比“被广泛使用”自然。","trap":{"wrong":"The bridge was build in 1990.","right":"The bridge was built in 1990.","note":"被动语态要用过去分词 built，build 是不规则动词，不能写原形。"},"examples":[{"en":"Many ancient buildings were damaged in the earthquake.","zh":"许多古建筑在地震中受损。"},{"en":"English is spoken as a second language in many countries.","zh":"英语在许多国家被当作第二语言使用。"}],"understanding":"被动语态由 be+过去分词构成，主语是动作的承受者，不是发出者。","translation":"中文可译“被……”，但更常转成主动句或无主句，“广泛使用”比“被广泛使用”自然。"},
{"key":"passive-modal","label":"情态动词 + 被动语态","definition":"情态动词+be+过去分词构成情态被动，表示“可以被、应该被、必须被……”。","identify":"看到 can/must/should/may+be+过去分词，就是情态被动；看主语是不是动作承受者。","usage":"公式：情态动词+be+过去分词。can be solved 可以被解决，must be checked 必须被检查。情态动词后永远是 be，不能换成 am/is/are。否定把 not 放在情态动词后。","translate":"译成“可以……”“应该……”“必须……”，中文常省掉“被”字，改成主动句。","trap":{"wrong":"The problem can solved in two ways.","right":"The problem can be solved in two ways.","note":"情态动词后面必须先接 be，再接过去分词，不能省掉 be 这一步。"},"examples":[{"en":"All applications must be submitted before the deadline.","zh":"所有申请都必须在截止日期前提交。"},{"en":"Such behavior should not be tolerated in any workplace.","zh":"这种行为在任何工作场所都不应被容忍。"}],"understanding":"情态动词+be+过去分词构成情态被动，表示“可以被、应该被、必须被……”。","translation":"译成“可以……”“应该……”“必须……”，中文常省掉“被”字，改成主动句。"},
{"key":"active-passive","label":"主动形式表被动（sell well / wash easily）","definition":"主动形式表被动指某些动词用主动形式，意义上却是被动，常说明主语的属性。","identify":"看到 sell、wash、read、write、open 等动词，后跟 well、easily 等副词，主语又是物，就按被动理解。","usage":"结构：主语（物）+动词+副词。This book sells well 这本书很畅销；The cloth washes easily 这种布很好洗。这类句子强调事物属性，不能改成被动，也不能加 by。","translate":"译成“很好卖、很好洗、写起来很顺”，用“起来”“好……”表达，不要硬译“被卖”。","trap":{"wrong":"This kind of shirt is washed easily.","right":"This kind of shirt washes easily.","note":"说明衣物本身的属性时用主动形式 washes，加 is 反而变成一次具体动作。"},"examples":[{"en":"This new novel sells well among young readers.","zh":"这本新小说在年轻读者中很畅销。"},{"en":"The new fabric washes easily and dries quickly.","zh":"这种新面料很好洗，干得也快。"}],"understanding":"主动形式表被动指某些动词用主动形式，意义上却是被动，常说明主语的属性。","translation":"译成“很好卖、很好洗、写起来很顺”，用“起来”“好……”表达，不要硬译“被卖”。"},
{"key":"get-passive","label":"get + 过去分词（get-passive）","definition":"get+过去分词构成 get 被动，意思接近 be 被动，但更口语，常强调变化或意外。","identify":"看到 get+过去分词，如 get paid、get hurt、get promoted，且主语是承受者，就是 get 被动。","usage":"公式：get+过去分词，时态由 get 变化：got married、will get fired。它比 be 被动更口语，多用于不好的或突然的事：get hurt、get lost。正式文体仍用 be。","translate":"译成“被……”“遭到……”“变得……”，如 get paid 译“拿到报酬”。","trap":{"wrong":"He got injure in the accident.","right":"He got injured in the accident.","note":"get 后面要接过去分词 injured，不能用动词原形，get 被动也要分词。"},"examples":[{"en":"She got promoted after working there for only two years.","zh":"她在那里只工作了两年就升职了。"},{"en":"Several houses got badly damaged during the storm last night.","zh":"昨晚的暴风雨中，好几栋房子严重受损。"}],"understanding":"get+过去分词构成 get 被动，意思接近 be 被动，但更口语，常强调变化或意外。","translation":"译成“被……”“遭到……”“变得……”，如 get paid 译“拿到报酬”。"},
{"key":"have-sth-done","label":"have / get + 宾语 + 过去分词（请人做 / 让某事被做）","definition":"have/get+宾语+过去分词表示请别人做某事，或某事被（意外）做在自己身上。","identify":"看到 have 或 get 后先接名词，再接过去分词，如 have my hair cut，就是使役被动结构。","usage":"公式：have/get+宾语+过去分词。宾语和分词是被动关系。三种意思：请人做（have my car repaired）、遭遇不幸（have my wallet stolen）、完成（get the work finished）。","translate":"译成“请人……”“让……被……”“遭遇到……”，根据语境选，不要译“有……”。","trap":{"wrong":"I had my hair cutting yesterday.","right":"I had my hair cut yesterday.","note":"宾语 hair 和 cut 是被动关系，要用过去分词 cut，不能用 cutting。"},"examples":[{"en":"They had the old house painted before moving in.","zh":"搬进去之前他们请人把老房子粉刷了一遍。"},{"en":"She got her phone stolen on the crowded bus.","zh":"她在拥挤的公交车上被人偷了手机。"}],"understanding":"have/get+宾语+过去分词表示请别人做某事，或某事被（意外）做在自己身上。","translation":"译成“请人……”“让……被……”“遭遇到……”，根据语境选，不要译“有……”。"},
{"key":"make-let-do","label":"make / let / have + 宾语 + 动词原形","definition":"make/let/have+宾语+动词原形表示“使、让、叫某人做某事”，不定式不带 to。","identify":"看到 make、let、have 后先接人或物，再直接接动词原形、中间没有 to，就是使役结构。","usage":"公式：make/let/have+sb+do sth。make 偏“迫使”，let 偏“允许”，have 偏“安排”。变被动时 make 后的 to 要还原：He was made to work overtime。","translate":"译成“使/让/叫某人做某事”。被动句里 make 要译“被迫……”，别漏语气。","trap":{"wrong":"My parents let me to choose my own major.","right":"My parents let me choose my own major.","note":"let 后面接动词原形，不能加 to，这是使役动词的共同特点。"},"examples":[{"en":"The teacher made us rewrite the whole essay.","zh":"老师让我们把整篇文章重写一遍。"},{"en":"Let me explain to you why the plan failed.","zh":"让我向你解释这个计划为什么失败。"}],"understanding":"make/let/have+宾语+动词原形表示“使、让、叫某人做某事”，不定式不带 to。","translation":"译成“使/让/叫某人做某事”。被动句里 make 要译“被迫……”，别漏语气。"},
{"key":"modal-basic","label":"情态动词（can / must / should / may 的能力、义务与推测）","definition":"情态动词表示能力、义务、允许或推测，后面必须接动词原形，没有人称变化。","identify":"看到 can、may、must、should、would，后面直接跟动词原形；它不加 -s，也不用 do 提问。","usage":"按功能记：can/could 表能力或可能；must 表必须或强推测；should 表应该；may/might 表允许或弱推测。否定：cannot、must not 禁止、need not 不必。推测由强到弱：must>may>might。","translate":"can 译“能、可以”，must 译“必须、一定”，should 译“应该”，may 译“可能”。","trap":{"wrong":"He can plays the piano very well.","right":"He can play the piano very well.","note":"情态动词没有人称和数的变化，后面必须用动词原形，不能加 -s。"},"examples":[{"en":"You must wear a helmet when riding a motorcycle.","zh":"骑摩托车时必须戴头盔。"},{"en":"Such an error may occur when the data are incomplete.","zh":"数据不完整时可能出现这种错误。"}],"understanding":"情态动词表示能力、义务、允许或推测，后面必须接动词原形，没有人称变化。","translation":"can 译“能、可以”，must 译“必须、一定”，should 译“应该”，may 译“可能”。"},
{"key":"modal-perfect","label":"情态动词 + have done（对过去的推测/评价）","definition":"情态动词+have done 表示对过去情况的推测或评价，动作发生在过去。","identify":"看到 must/may/might/could/should/needn't+have+过去分词，就是情态完成式，讨论已发生的事。","usage":"must have done 一定做过；may have done 可能做过；could have done 本来能做而没做；should have done 本该做而没做。重点在推断或评价，不能换成一般过去时。","translate":"must have done 译“一定……”；should have done 译“本应该……”。","trap":{"wrong":"You should went to see the doctor earlier.","right":"You should have gone to see the doctor earlier.","note":"对过去的评价要用 should have+过去分词，不能直接接过去式 went。"},"examples":[{"en":"The lights are off; they must have left already.","zh":"灯关着，他们一定已经走了。"},{"en":"We needn't have booked the tickets so early.","zh":"我们本不必这么早订票。"}],"understanding":"情态动词+have done 表示对过去情况的推测或评价，动作发生在过去。","translation":"must have done 译“一定……”；should have done 译“本应该……”。"},
{"key":"modal-advanced","label":"情态进阶（need / dare / ought to / had better）","definition":"need 和 dare 是半情态动词，兼有情态和实义两种用法；ought to 和 had better 是情态短语，后面一律接动词原形。","identify":"need/dare 用于否定和疑问时可作情态动词，后接动词原形、不加 to；作实义动词时第三人称加 -s、后面接 to do。ought to 和 had better 后面一律接动词原形。","usage":"need 作情态动词：Need I say more? / You needn't worry；作实义动词：He needs to see a doctor。dare 同理：Dare you ask her? / He dares to speak。ought to 表示“应该”，否定是 ought not to；had better 表示“最好”，否定是 had better not，后面不加 to。回答 need 的疑问句时，肯定用 must，否定用 needn't。判断是情态还是实义，看形式和主语：后面直接跟动词原形、疑问和否定不加 do 的是情态，第三人称单数加 -s、后面接 to do 的是实义。","translate":"needn't 译“不必”，mustn't 译“禁止”；ought to 译“应该”；had better 译“最好”，had better not 译“最好别”，语气都比 should 更口语。ought to 的否定也可缩写成 oughtn't to，had better 的否定直接在后面加 not。","trap":{"wrong":"You had better not to stay up late.","right":"You had better not stay up late.","note":"had better 后直接接动词原形，否定形式是 had better not do，不能加 to，也不要写成 hadn't better；它比 should 语气更强，多用于提醒和劝告。"},"examples":[{"en":"You needn't book a table; the restaurant is never full on weekdays.","zh":"你不必订位，这家餐厅工作日从不坐满。"},{"en":"She ought to apologize for what she said at the meeting.","zh":"她应该为会上说的话道歉。"},{"en":"Dare he tell the truth in front of everyone?","zh":"他敢当着所有人的面说出真相吗？"}],"understanding":"need 和 dare 是半情态动词，兼有情态和实义两种用法；ought to 和 had better 是情态短语，后面一律接动词原形。","translation":"needn't 译“不必”，mustn't 译“禁止”；ought to 译“应该”；had better 译“最好”，had better not 译“最好别”，语气都比 should 更口语。ought to 的否定也可缩写成 oughtn't to，had better 的否定直接在后面加 not。"},
{"key":"gerund-subject","label":"动名词作主语 / 介词宾语（doing）","definition":"动名词 doing 可作主语或介词宾语，表示习惯性、抽象的动作，不作谓语。","identify":"句首是动词-ing 且后跟 helps、is 等谓语，或者介词后面出现动词-ing，就是动名词。","usage":"动名词作主语，谓语用单数：Reading widely helps…。介词后必须用动名词：by doing、without doing、look forward to doing。注意 to 也可能是介词。","translate":"译成“……（这件事）”，不必译“正在”；作介词宾语时按中文语序调整。","trap":{"wrong":"Read widely help students build vocabulary.","right":"Reading widely helps students build vocabulary.","note":"动词原形不能作主语，要改成动名词 Reading，谓语也用单数 helps。"},"examples":[{"en":"Learning a second language takes years of practice.","zh":"学习第二语言需要多年的练习。"},{"en":"She improved her English by watching films without subtitles.","zh":"她通过看无字幕电影提高了英语。"}],"understanding":"动名词 doing 可作主语或介词宾语，表示习惯性、抽象的动作，不作谓语。","translation":"译成“……（这件事）”，不必译“正在”；作介词宾语时按中文语序调整。"},
{"key":"participle-attribute","label":"分词作定语（后置 done / 前置 doing）","definition":"分词作定语是用 doing 或 done 修饰名词，doing 表主动，done 表被动。","identify":"单个分词常放名词前（rising prices），分词短语常放名词后（the data collected），修饰该名词。","usage":"判断主动还是被动：名词发出动作用 doing，承受动作用 done。后置 done 短语相当于被动定语从句：the data collected=the data that were collected。先找逻辑主语。","translate":"译成“……的”放名词前：“收集到的数据”“上涨的成本”，不要译“正在被……”那么生硬。","trap":{"wrong":"The data collecting by the team were incomplete.","right":"The data collected by the team were incomplete.","note":"data 是被收集的，要用过去分词 collected，不能用表示主动的 collecting。"},"examples":[{"en":"The report published last week attracted wide attention.","zh":"上周发表的那份报告引起了广泛关注。"},{"en":"Rising costs have forced many small shops to close.","zh":"不断上涨的成本迫使许多小店关门。"}],"understanding":"分词作定语是用 doing 或 done 修饰名词，doing 表主动，done 表被动。","translation":"译成“……的”放名词前：“收集到的数据”“上涨的成本”，不要译“正在被……”那么生硬。"},
{"key":"participle-phrase","label":"句中分词短语（, doing / done 补充说明）","definition":"句中分词短语用逗号隔开，对主句作补充说明，可表原因、伴随、结果或条件。","identify":"看到逗号后面出现 doing 或 done 短语，而且它的逻辑主语就是主句主语，就是分词短语。","usage":"两步：先找主句主语，再看它和分词是主动还是被动。主动用 doing，被动用 done。位置可在句末或句中：The plan, designed by experts, was approved。","translate":"译成一个短句：“……着”“由于……”“这一……由……设计”，不要硬塞进定语位置。","trap":{"wrong":"Having finished the report, the computer was turned off.","right":"Having finished the report, she turned off the computer.","note":"分词短语的逻辑主语必须和主句主语一致，电脑不会写报告，否则句子就错了。"},"examples":[{"en":"The company, founded in 1998, now employs over five thousand people.","zh":"这家公司成立于 1998 年，现在雇有五千多人。"},{"en":"He sat by the window, watching the rain fall.","zh":"他坐在窗边，看着雨落下来。"}],"understanding":"句中分词短语用逗号隔开，对主句作补充说明，可表原因、伴随、结果或条件。","translation":"译成一个短句：“……着”“由于……”“这一……由……设计”，不要硬塞进定语位置。"},
{"key":"participle-adverbial","label":"分词作状语（doing / done 开头）","definition":"分词作状语放句首或句末，用 doing 或 done 表时间、原因、条件、让步或伴随。","identify":"句首出现 Doing…或 Done…，后面用逗号接主句，且分词逻辑主语就是主句主语，就是分词作状语。","usage":"主动关系用 doing，被动关系用 done；先发生的动作用 having done。常见：Faced with…面对，Compared with…与……相比。一定要检查逻辑主语，否则会出现悬垂分词。","translate":"译成“面对……”“考虑到……”“与……相比”，先译状语，再译主句。","trap":{"wrong":"Walking along the street, the accident was seen by him.","right":"Walking along the street, he saw the accident.","note":"走路的只能是人，分词逻辑主语要和主句主语 he 一致，不能用被动句。"},"examples":[{"en":"Faced with strong competition, the firm changed its strategy.","zh":"面对激烈的竞争，这家公司改变了策略。"},{"en":"Compared with last year, online sales have doubled.","zh":"与去年相比，线上销售额翻了一番。"}],"understanding":"分词作状语放句首或句末，用 doing 或 done 表时间、原因、条件、让步或伴随。","translation":"译成“面对……”“考虑到……”“与……相比”，先译状语，再译主句。"},
{"key":"infinitive-purpose","label":"不定式作目的 / 结果 / 定语（to do）","definition":"不定式 to do 可表目的、结果，也可放名词后作定语，说明要做的动作。","identify":"看到 to+动词原形，先判断它是否回答“为了什么”，或紧跟 ability、chance、way 等名词。","usage":"作目的：He left early to catch the train；作结果：He woke up to find everyone gone；作定语：the ability to adapt。不定式作定语时常和名词有动宾或主谓关系。","translate":"作目的译“为了……”；作定语译“做……的”；作结果译“结果却……”。","trap":{"wrong":"She studies hard for passing the exam.","right":"She studies hard to pass the exam.","note":"表示目的用不定式 to do，不用 for+doing，for 后一般接名词。"},"examples":[{"en":"Many students take part-time jobs to gain work experience.","zh":"许多学生做兼职是为了获得工作经验。"},{"en":"He returned home to find the door wide open.","zh":"他回到家，却发现门大开着。"}],"understanding":"不定式 to do 可表目的、结果，也可放名词后作定语，说明要做的动作。","translation":"作目的译“为了……”；作定语译“做……的”；作结果译“结果却……”。"},
{"key":"only-to","label":"only to do 出乎意料的结果","definition":"only to do 表示“结果却……”，引出出乎意料、往往令人失望的结果。","identify":"看到逗号后出现 only to+动词原形，前面是完整动作，就是“结果却”，不是“仅仅为了”。","usage":"公式：主句+only to do。它表示前面的动作产生了意外结果，常带遗憾：He hurried to the station only to find the train had left。这里 only 不表示“仅仅”，to 后接原形。","translate":"译成“结果却……”“不料……”，不要译成“只是为了……”，要译出意外。","trap":{"wrong":"She opened the box, only finding it empty.","right":"She opened the box, only to find it empty.","note":"only 表示意外结果时固定接不定式 to do，不能换成 doing。"},"examples":[{"en":"He rushed to the airport only to discover his flight was cancelled.","zh":"他赶到机场，却发现航班取消了。"},{"en":"She searched the whole house only to find the keys in her pocket.","zh":"她找遍了整座房子，结果发现钥匙就在自己口袋里。"}],"understanding":"only to do 表示“结果却……”，引出出乎意料、往往令人失望的结果。","translation":"译成“结果却……”“不料……”，不要译成“只是为了……”，要译出意外。"},
{"key":"perception-verb","label":"感官动词 + 宾语 + do / doing / done","definition":"感官动词 see/hear/watch 后接宾语，再接 do、doing 或 done。","identify":"看到 see、hear、watch、notice、feel 后先接人或物，再直接接动词，就要判断用 do、doing 还是 done。","usage":"三种形式：+do 表看到整个动作；+doing 表动作正在进行；+done 表宾语和动作是被动关系。如 I saw him cross、I saw him crossing、I saw him taken away。","translate":"do 译“看见某人做了”，doing 译“看见某人正在做”，done 译“看见某人被……”。","trap":{"wrong":"I saw him to cross the street.","right":"I saw him cross the street.","note":"感官动词主动句中接动词原形，不加 to；只有变被动时才还原 to。"},"examples":[{"en":"We watched the children playing football in the park.","zh":"我们看着孩子们在公园里踢球。"},{"en":"I heard my name called from across the room.","zh":"我听到房间另一头有人叫我的名字。"}],"understanding":"感官动词 see/hear/watch 后接宾语，再接 do、doing 或 done。","translation":"do 译“看见某人做了”，doing 译“看见某人正在做”，done 译“看见某人被……”。"},
{"key":"nonfinite-advanced","label":"非谓语进阶（having done / being done）","definition":"having done 和 being done 是分词的进阶形式，专门用来把两个动作的先后顺序或主动被动关系说清楚。","identify":"having done 表示动作发生在谓语之前，且逻辑主语是主动的；being done 表示与谓语同时发生，且逻辑主语是被动的；两者都常出现在句首或逗号后作状语。","usage":"先找逻辑主语，再看它和谓语的时间关系：动作先发生且逻辑主语是主动的，用 having done，如 Having finished the report, she went home；动作同时进行且逻辑主语是被动的，用 being done，如 Being asked to speak, he stood up。否定式把 not 放最前面：Not having received a reply, he wrote again。这两种形式都不能单独作谓语，句中真正的谓语仍由主句提供。","translate":"having done 译“……之后/因为已经……”；being done 译“由于被……/在被……时”；中文按时间顺序先译状语，再译主句，不必保留分词形式。","trap":{"wrong":"Having finished his homework, the TV was turned on.","right":"Having finished his homework, he turned on the TV.","note":"分词作状语时逻辑主语必须和主句主语一致；作业不是打开电视的人，这是悬垂分词。"},"examples":[{"en":"Having lived in the city for years, she knew every corner of it.","zh":"在这座城市住了多年，她熟悉它的每一个角落。"},{"en":"Being constantly interrupted, the speaker lost her train of thought.","zh":"由于不断被打断，演讲者乱了思路。"},{"en":"Not having been informed of the change, the staff arrived late.","zh":"由于没有被告知变动，员工们来晚了。"}],"understanding":"having done 和 being done 是分词的进阶形式，专门用来把两个动作的先后顺序或主动被动关系说清楚。","translation":"having done 译“……之后/因为已经……”；being done 译“由于被……/在被……时”；中文按时间顺序先译状语，再译主句，不必保留分词形式。"},
{"key":"have-difficulty","label":"have difficulty / trouble (in) doing","definition":"have difficulty/trouble doing 表示“做某事有困难、很费劲”。","identify":"看到 have difficulty、trouble、problems，后面跟动词-ing，就是这一结构，in 可省略。","usage":"公式：have difficulty/trouble (in)+doing。difficulty 可数时用 difficulties。否定 have no difficulty doing 表示毫无困难。不能用 to do。","translate":"译成“做……有困难”“做……很费劲”，不要按字面译“在里面有困难”。","trap":{"wrong":"Many students have difficulty to concentrate in class.","right":"Many students have difficulty concentrating in class.","note":"have difficulty 后面固定接动名词 doing，不能接不定式 to do。"},"examples":[{"en":"She had difficulty understanding the professor's accent at first.","zh":"起初她很难听懂教授的口音。"},{"en":"Few people have trouble finding the station from here.","zh":"很少有人会从这里找不到车站。"}],"understanding":"have difficulty/trouble doing 表示“做某事有困难、很费劲”。","translation":"译成“做……有困难”“做……很费劲”，不要按字面译“在里面有困难”。"},
{"key":"spend-time","label":"spend / waste time (in) doing","definition":"spend/waste time (in) doing 表示“花/浪费时间做某事”，后面接动名词。","identify":"看到 spend、waste 后面先接时间，再接动词-ing，就是这一结构；也常见 spend time on+名词。","usage":"公式：spend/waste+时间+(in)+doing sth；spend+钱+on+名词。主语必须是人，in 可省略。不能把 doing 改成 to do，也不能说 spend time to do。","translate":"译成“花/浪费时间做某事”，中文把“做某事”放后面，不要把 in 译出来。","trap":{"wrong":"She spends two hours to read every evening.","right":"She spends two hours reading every evening.","note":"spend time 后面固定接动名词 doing，不能接不定式 to do。"},"examples":[{"en":"He spends most of his free time reading and writing.","zh":"他把大部分空闲时间都用来读书和写作。"},{"en":"They wasted three hours waiting for a bus that never came.","zh":"他们白等了三个小时，那趟公交始终没来。"}],"understanding":"spend/waste time (in) doing 表示“花/浪费时间做某事”，后面接动名词。","translation":"译成“花/浪费时间做某事”，中文把“做某事”放后面，不要把 in 译出来。"},
{"key":"prefer-to","label":"prefer A to B / would rather … than","definition":"prefer A to B 表示“比起 B 更喜欢 A”，to 是介词，前后要用对等成分。","identify":"看到 prefer 后接两个名词或两个动名词，中间用 to 连接，就是“比起……更喜欢……”。","usage":"三种形式：prefer+名词/doing+to+名词/doing；prefer to do+rather than+do；would rather+do+than+do。to 是介词，前后成分要对等。","translate":"译成“比起 B 更喜欢 A”“宁愿……而不愿……”，A 放在“喜欢”后面。","trap":{"wrong":"I prefer reading to watch TV.","right":"I prefer reading to watching TV.","note":"prefer A to B 中 to 是介词，前后要对称，都用动名词。"},"examples":[{"en":"She prefers working with numbers to dealing with customers.","zh":"比起和客户打交道，她更喜欢和数字打交道。"},{"en":"He would rather resign than accept such unfair terms.","zh":"他宁愿辞职也不愿接受这样不公平的条件。"}],"understanding":"prefer A to B 表示“比起 B 更喜欢 A”，to 是介词，前后要用对等成分。","translation":"译成“比起 B 更喜欢 A”“宁愿……而不愿……”，A 放在“喜欢”后面。"},
{"key":"be-about-to","label":"be about to do / be on the point of doing","definition":"be about to do 和 be on the point of doing 都表示“即将”。","identify":"看到 am/is/are/was/were about to+动词原形，或 on the point of+doing，就是“即将”结构。","usage":"公式：be about to do；be on the point of doing。它比 be going to 更近、更急。常见：I was about to leave when the phone rang。","translate":"译成“正要……”“即将……”，when 从句译“这时突然……”，把紧迫感译出来。","trap":{"wrong":"We are about to leaving when it started to rain.","right":"We are about to leave when it started to rain.","note":"be about to 后面接动词原形，不能接 doing；on the point of 后才接 doing。"},"examples":[{"en":"The train is about to depart from platform three.","zh":"火车即将从三号站台发车。"},{"en":"She was on the point of giving up when the results arrived.","zh":"她正要放弃时，结果送到了。"}],"understanding":"be about to do 和 be on the point of doing 都表示“即将”。","translation":"译成“正要……”“即将……”，when 从句译“这时突然……”，把紧迫感译出来。"},
{"key":"too-enough","label":"too … to / … enough to 结构","definition":"too…to 表示“太……以至于不能……”，…enough to 表示“足够……可以……”。","identify":"看到 too+形容词/副词+to do，或形容词/副词+enough+to do，就是这两种结果结构。","usage":"too+adj./adv.+to do 形式没有 not，意思却是否定：The box is too heavy to carry。enough 放在形容词后：old enough to drive。for sb 可插在 to do 前。","translate":"too…to 译“太……而不能……”；enough to 译“足够……可以做……”。","trap":{"wrong":"The box is too heavy to carry it.","right":"The box is too heavy to carry.","note":"不定式 carry 的宾语就是前面的 the box，后面再加 it 会重复。"},"examples":[{"en":"The evidence is too weak to support such a strong claim.","zh":"证据太薄弱，无法支持这样有力的论断。"},{"en":"He is old enough to make his own decisions.","zh":"他已经到了可以自己做决定的年龄。"}],"understanding":"too…to 表示“太……以至于不能……”，…enough to 表示“足够……可以……”。","translation":"too…to 译“太……而不能……”；enough to 译“足够……可以做……”。"},
{"key":"nothing-but","label":"nothing but / anything but 否定强调结构","definition":"nothing but 表示“只不过、仅仅是”，anything but 表示“绝不是”。","identify":"看到 nothing but 或 anything but，后接名词、代词或动词原形，先判断是“只是”还是“绝不是”。","usage":"nothing but=only，强调“仅仅”：He is nothing but a beginner。anything but=not at all，强烈否定：The task is anything but easy。","translate":"nothing but 译“只不过是”；anything but 译“绝不是、一点也不”。","trap":{"wrong":"The exam was nothing but easy; everyone struggled.","right":"The exam was anything but easy; everyone struggled.","note":"句意是“一点也不容易”，要用 anything but；nothing but 是“只是”。"},"examples":[{"en":"The problem is anything but simple; it involves several departments.","zh":"这个问题绝不简单，它涉及好几个部门。"},{"en":"What he said was nothing but an excuse.","zh":"他所说的不过是个借口。"}],"understanding":"nothing but 表示“只不过、仅仅是”，anything but 表示“绝不是”。","translation":"nothing but 译“只不过是”；anything but 译“绝不是、一点也不”。"},
{"key":"the-last","label":"the last + 名词 + to do / that …（最不可能……）","definition":"the last+名词+to do/that… 表示“最不可能……的”，不是“最后一个”。","identify":"看到 the last person/thing+to do，或 the last+名词+that 从句，且句意是“绝不会”，就是这一用法。","usage":"the last+名词+to do 表示“最不可能做某事的”：He is the last person to tell a lie。它靠上下文表强烈否定，不能按字面译“最后一个”。","translate":"译成“最不可能……的”“绝不会……的”，不要按字面译“最后一个……”。","trap":{"wrong":"She is the last person to telling lies.","right":"She is the last person to tell lies.","note":"the last+名词 后接不定式 to do，不能接 doing；这里意为“最不可能”。"},"examples":[{"en":"He is the last person to complain about working late.","zh":"他是最不可能抱怨加班的人。"},{"en":"This is the last place I would expect to meet him.","zh":"这是我最不可能想到会遇见他的地方。"}],"understanding":"the last+名词+to do/that… 表示“最不可能……的”，不是“最后一个”。","translation":"译成“最不可能……的”“绝不会……的”，不要按字面译“最后一个……”。"},
{"key":"adjective-postmodifier","label":"形容词后置定语（something important / people present）","definition":"形容词后置定语指形容词放在名词后修饰它，常见于复合不定代词后。","identify":"看到 something、anything 后跟形容词，或 people present 这类结构，就是形容词后置。","usage":"两类情况：一、修饰 something/anything/nothing/everything 时形容词必须后置：something important；二、present 后置更具体：the people present。","translate":"译成“……的（东西/人）”，按中文习惯把形容词放回名词前，如“重要的事”。","trap":{"wrong":"I have important something to tell you.","right":"I have something important to tell you.","note":"修饰复合不定代词时形容词必须后置，放在 something 后面。"},"examples":[{"en":"Is there anything else you would like to add?","zh":"你还有什么想补充的吗？"},{"en":"All the people present agreed with the proposal.","zh":"所有在场的人都同意这项提议。"}],"understanding":"形容词后置定语指形容词放在名词后修饰它，常见于复合不定代词后。","translation":"译成“……的（东西/人）”，按中文习惯把形容词放回名词前，如“重要的事”。"},
{"key":"five-patterns","label":"五种基本句型（SV / SVO / SVP / SVOO / SVOC）","definition":"英语里的句子基本都能归到五种基本句型，区别只在谓语动词后面跟了什么成分，骨架永远只有一套。","identify":"先找谓语动词，再看它后面跟了没有、跟几个：后面不跟宾语是 SV，跟一个宾语是 SVO，跟表语是 SVP，跟两个宾语是 SVOO，宾语后还有补语是 SVOC。","usage":"先立住主语和谓语，再数谓语后面跟几样：不跟宾语是 SV，跟一个宾语是 SVO，跟表语是 SVP，跟两个宾语是 SVOO，宾语后还有补语是 SVOC。区分 SVOO 和 SVOC，只需在两个成分之间加 be：讲得通的是补语，如 They elected him chairman；讲不通的是双宾语，如 He gave me a book。","translate":"按“谁—做什么—对谁—怎么样”的中文顺序译；SVP 把表语译成“是……的”，SVOC 常译成“使/让……怎么样”。","trap":{"wrong":"The news made him happily.","right":"The news made him happy.","note":"make 后接形容词作宾语补足语，表示“使某人处于某种状态”，不能用副词 happily；him 和 happy 之间能加 be，属于 SVOC 结构。"},"examples":[{"en":"The teacher asked us to hand in our essays by Friday.","zh":"老师要求我们在周五前交论文。"},{"en":"The old bridge has stood there for more than a century.","zh":"这座老桥在那里矗立了一个多世纪。"},{"en":"She offered the guests a warm cup of tea.","zh":"她给客人们端上一杯热茶。"}],"understanding":"英语里的句子基本都能归到五种基本句型，区别只在谓语动词后面跟了什么成分，骨架永远只有一套。","translation":"按“谁—做什么—对谁—怎么样”的中文顺序译；SVP 把表语译成“是……的”，SVOC 常译成“使/让……怎么样”。"},
{"key":"sentence-elements","label":"句子成分（主谓宾定状补）","definition":"句子成分是词或短语在句中担任的角色：主语、谓语、宾语、定语、状语、补语，各司其职，缺一不可。","identify":"主语是动作的发出者，谓语是动作或状态，宾语是动作承受者；定语修饰名词，状语修饰动词或整句，补语补充说明宾语或主语，删掉意思就不完整。","usage":"拆句顺序：先圈谓语动词，再往前找主语，往后找宾语；名词前后的修饰是定语；表示时间、地点、原因、方式、程度的是状语；宾语后说明“它怎么样/是什么”的是补语。定语回答“哪一个”，状语回答“何时何地为何如何”，补语回答“怎么样”。","translate":"中文按“定语前置、状语灵活、补语后置”处理：定语加“的”，状语常放动词前，补语译成“得……”或“使……”。","trap":{"wrong":"She speaks English very good.","right":"She speaks English very well.","note":"修饰动词 speaks 要用副词 well，good 是形容词，只能作定语或表语，不能放在动词后面修饰动作。"},"examples":[{"en":"The students in the front row answered the question confidently.","zh":"前排的学生自信地回答了这个问题。"},{"en":"The committee considered the new proposal completely impractical.","zh":"委员会认为这个新提议完全不切实际。"},{"en":"We met an old friend at the station yesterday.","zh":"我们昨天在车站遇到了一位老朋友。"}],"understanding":"句子成分是词或短语在句中担任的角色：主语、谓语、宾语、定语、状语、补语，各司其职，缺一不可。","translation":"中文按“定语前置、状语灵活、补语后置”处理：定语加“的”，状语常放动词前，补语译成“得……”或“使……”。"},
{"key":"relative-clause","label":"限制性定语从句（that / which / who）","definition":"紧跟在名词后面、用来限定这个名词是哪一个的从句，删掉后句子意思会不完整。","identify":"找到先行词（被修饰的名词），看它后面是否直接跟 that / which / who，且从句里缺主语或宾语；从句前没有逗号。","usage":"结构：先行词 + that/which/who + 不完整从句。指物用 that 或 which，指人用 who，that 也可指人。判断：从句缺主语或宾语才用关系代词，缺状语用 where/when/why；介词后不能用 that。","translate":"译成“……的……”放在名词前；从句太长时拆成两个分句，用“这个/他/它”承接。","trap":{"wrong":"The book which I bought it yesterday is very useful.","right":"The book which I bought yesterday is very useful.","note":"关系代词 which 已在从句里作 bought 的宾语，不能再加 it，否则宾语重复。"},"examples":[{"en":"The scientist who discovered the vaccine received a major award.","zh":"发现这种疫苗的科学家获得了一项重要奖项。"},{"en":"This is the method that the team has used for years.","zh":"这就是团队用了多年的方法。"},{"en":"Students who read widely tend to write more clearly.","zh":"阅读广泛的学生往往写得更清楚。"}],"understanding":"紧跟在名词后面、用来限定这个名词是哪一个的从句，删掉后句子意思会不完整。","translation":"译成“……的……”放在名词前；从句太长时拆成两个分句，用“这个/他/它”承接。"},
{"key":"non-restrictive","label":"非限制性定语从句（, which / who …）","definition":"用逗号隔开的补充说明从句，删掉后主句仍然完整通顺，只起附加信息作用。","identify":"名词或整句后面先有逗号，再用 which / who / whom / whose 引导；不能用 that，也不能写成逗号加 that。","usage":"结构：主句, + which/who + 补充说明。which 可指前面的名词，也可指整个主句（此时译“这一点”）；who 指人。从句只是附加信息，不能缩小先行词范围。翻译时一般另起一句。","translate":"拆成两个短句：“……，这……”“……，他/它……”；指代整句时用“这一点/此事”。","trap":{"wrong":"He missed the train, that made him late for work.","right":"He missed the train, which made him late for work.","note":"非限制性定语从句不能用 that；指代前面整句时只能用 which。"},"examples":[{"en":"The project, which took three years, finally won national recognition.","zh":"这个项目耗时三年，最终获得了国家级的认可。"},{"en":"My mentor, who retired last month, still answers my emails.","zh":"我的导师上个月退休了，但他仍然回复我的邮件。"},{"en":"The company cut prices, which helped it win new customers.","zh":"这家公司降低了价格，这帮助它赢得了新客户。"}],"understanding":"用逗号隔开的补充说明从句，删掉后主句仍然完整通顺，只起附加信息作用。","translation":"拆成两个短句：“……，这……”“……，他/它……”；指代整句时用“这一点/此事”。"},
{"key":"relative-whose","label":"whose / of which 所属定语从句","definition":"表示“谁的、它的”的定语从句，whose 后面直接跟名词，用来说明所属关系。","identify":"先行词后出现 whose + 名词，或“the + 名词 + of which / of whom”结构；whose 可指人也可指物。","usage":"结构：先行词 + whose + 名词 + 从句。指物也可写成 the + 名词 + of which，如 the door of which。whose 在从句里作定语，后面必须紧跟名词，不能单独使用。","translate":"译成“……的……”：whose car 就是“他的车”；of which 结构同样译“的”，语序按中文调整。","trap":{"wrong":"The student whose his father is a doctor wants to study medicine.","right":"The student whose father is a doctor wants to study medicine.","note":"whose 本身已含“他的”，后面不能再加 his，否则所属重复。"},"examples":[{"en":"She lives in a house whose windows face the sea.","zh":"她住在一所窗户朝海的房子里。"},{"en":"The company, whose profits had fallen, decided to restructure.","zh":"这家公司利润下滑，决定进行重组。"},{"en":"This is a theory of which the origin remains unclear.","zh":"这是一个起源仍不清楚的理论。"}],"understanding":"表示“谁的、它的”的定语从句，whose 后面直接跟名词，用来说明所属关系。","translation":"译成“……的……”：whose car 就是“他的车”；of which 结构同样译“的”，语序按中文调整。"},
{"key":"relative-adverb","label":"where / when / why 关系副词定语从句","definition":"用 where、when、why 引导的定语从句，它们在从句里代替“介词 + 名词”，只作状语。","identify":"先行词是地点（place/city）、时间（day/time）或原因（reason），且从句成分完整、只缺状语时，才用关系副词。","usage":"where = in/at which，when = in/on which，why = for which。判断：从句缺主语或宾语用 which/that，缺状语才用关系副词。先行词是地点名词不一定就用 where，关键看从句缺什么成分。","translate":"译成“在那里/在那时/原因”等，通常把从句译到名词前作定语，或另起一句。","trap":{"wrong":"This is the city where I visited last year.","right":"This is the city that I visited last year.","note":"visited 缺宾语，应用 which/that；where 只能代替状语，不能作宾语。"},"examples":[{"en":"The village where she grew up has changed beyond recognition.","zh":"她长大的那个村庄已经变得认不出来了。"},{"en":"I still remember the day when we first met.","zh":"我仍然记得我们初次见面的那一天。"},{"en":"Nobody knows the reason why the plan was abandoned.","zh":"没有人知道这个计划被放弃的原因。"}],"understanding":"用 where、when、why 引导的定语从句，它们在从句里代替“介词 + 名词”，只作状语。","translation":"译成“在那里/在那时/原因”等，通常把从句译到名词前作定语，或另起一句。"},
{"key":"relative-who","label":"who / whom 定语从句（修饰人或人群）","definition":"先行词是人时使用的定语从句关系词，who 在从句中作主语，whom 作宾语。","identify":"先行词是 person、people、students 等指人的名词，后面紧跟 who 或 whom，且从句缺主语或宾语。","usage":"who 在从句中作主语，whom 作宾语（口语常用 who 代替）；介词后面只能用 whom，如 to whom。whose 表所属，who 不能直接放在介词后。判断：把从句还原成独立句，看关系词充当什么成分。","translate":"译成“……的（人）”，放在名词前；从句长时拆句，用“他/他们”承接。","trap":{"wrong":"The professor which teaches us history is very strict.","right":"The professor who teaches us history is very strict.","note":"先行词 professor 指人，关系代词要用 who 或 that，不能用 which。"},"examples":[{"en":"The doctor who treated her explained the risks carefully.","zh":"为她治疗的医生仔细解释了风险。"},{"en":"The candidates whom we interviewed all had strong backgrounds.","zh":"我们面试过的候选人都很有背景。"},{"en":"She is the colleague to whom I owe the most.","zh":"她是我最应该感谢的同事。"}],"understanding":"先行词是人时使用的定语从句关系词，who 在从句中作主语，whom 作宾语。","translation":"译成“……的（人）”，放在名词前；从句长时拆句，用“他/他们”承接。"},
{"key":"where-clause","label":"where 引导的从句（地点状语 / 定语从句）","definition":"where 可引导地点状语从句、定语从句，也可引导名词性从句，意思和功能随位置而变。","identify":"看 where 前有没有先行词：有地点名词是定语从句；没有先行词、直接修饰主句动词是状语从句；放在 know 等动词后是宾语从句。","usage":"定语从句：the house where I live；状语从句：Sit where you like；名词性从句：I don't know where he lives。判断看有无先行词和从句缺什么成分。","translate":"定语从句译“……的（地方）”；状语从句译“在……的地方”；名词性从句译“在哪里”，并按陈述句调整语序。","trap":{"wrong":"I don't know where does he live.","right":"I don't know where he lives.","note":"where 引导宾语从句时用陈述语序，不能保留疑问句的倒装。"},"examples":[{"en":"Where there is demand, new businesses soon appear.","zh":"哪里有需求，新的生意很快就会出现在哪里。"},{"en":"This is the office where the interviews take place.","zh":"这就是进行面试的办公室。"},{"en":"She asked me where I had bought the dictionary.","zh":"她问我这本词典是在哪里买的。"}],"understanding":"where 可引导地点状语从句、定语从句，也可引导名词性从句，意思和功能随位置而变。","translation":"定语从句译“……的（地方）”；状语从句译“在……的地方”；名词性从句译“在哪里”，并按陈述句调整语序。"},
{"key":"as-relative","label":"as 引导定语从句（such / the same / as is known）","definition":"as 引导的定语从句，指代前面整句或 such、the same 修饰的名词，位置比较灵活。","identify":"常见信号：such … as、the same … as、as is known、as we all know，as 后面跟一个从句。","usage":"such + 名词 + as 表示“像……这样的”；the same + 名词 + as 表示“和……同类的”（用 that 指同一个）。as 指代整句时可放句首：As is known to all, …。","translate":"译成“正如……”“像……这样的”；指代整句时译“这一点/这种情况”，常放句首。","trap":{"wrong":"As is known to all, that the earth moves around the sun.","right":"As is known to all, the earth moves around the sun.","note":"as 已引导从句并作主语，后面不能再加 that，也不能只剩一个名词短语。"},"examples":[{"en":"As is often the case, the simplest solution worked best.","zh":"正如常见的情况那样，最简单的方案效果最好。"},{"en":"Such books as you mentioned are hard to find now.","zh":"你提到的那类书现在很难找到。"},{"en":"He uses the same dictionary as I do.","zh":"他用的词典和我的一样。"}],"understanding":"as 引导的定语从句，指代前面整句或 such、the same 修饰的名词，位置比较灵活。","translation":"译成“正如……”“像……这样的”；指代整句时译“这一点/这种情况”，常放句首。"},
{"key":"prep-which","label":"介词 + which / whom 引导定语从句","definition":"把介词提到关系词前面的定语从句，介词由从句中动词或形容词的搭配决定。","identify":"看到 which / whom 前面直接有介词（in、on、by、with、to、for 等），且前面有先行词或逗号，就是这种结构。","usage":"结构：先行词 + 介词 + which/whom + 从句。还原时把介词放回从句末尾：the method by which = by the method。介词看搭配，如 depend on；指人只能用 whom。","translate":"译成“……的……”，把介词含义（通过、凭借、关于、在……中）译出来，不必保留英文语序。","trap":{"wrong":"The tool with that he fixed the car is missing.","right":"The tool with which he fixed the car is missing.","note":"介词后面不能用 that；指物用 which，指人用 whom。"},"examples":[{"en":"The rate at which the population grows has slowed down.","zh":"人口增长的速度已经放缓。"},{"en":"These are the principles on which the design is based.","zh":"这些就是该设计所依据的原则。"},{"en":"The colleague to whom I spoke was extremely helpful.","zh":"和我交谈的那位同事非常乐于助人。"}],"understanding":"把介词提到关系词前面的定语从句，介词由从句中动词或形容词的搭配决定。","translation":"译成“……的……”，把介词含义（通过、凭借、关于、在……中）译出来，不必保留英文语序。"},
{"key":"noun-clause","label":"名词性从句（what / whether / that 引导）","definition":"在句中充当主语、宾语、表语或同位语的从句，整体相当于一个名词。","identify":"从句出现在动词后、句首、be 动词后或抽象名词后，且由 what / whether / that 引导；从句一律用陈述语序。","usage":"what 在从句中作主语或宾语，意为“……的东西”；whether 意为“是否”，不作成分；that 只连接、不译、不作成分。判断：从句缺成分用 what，不缺成分且表“是否”用 whether，不缺成分且为陈述用 that。","translate":"what 译“……的（东西/事）”；whether 译“是否”；that 不译，直接按陈述句译。","trap":{"wrong":"That he said at the meeting surprised everyone.","right":"What he said at the meeting surprised everyone.","note":"said 缺宾语，应用 what；that 不作成分，不能充当宾语。"},"examples":[{"en":"What she needs most is a quiet place to study.","zh":"她最需要的是一个安静的学习场所。"},{"en":"I doubt whether the plan can be completed on time.","zh":"我怀疑这个计划能否按时完成。"},{"en":"That he passed the exam surprised no one.","zh":"他通过考试没有人感到意外。"}],"understanding":"在句中充当主语、宾语、表语或同位语的从句，整体相当于一个名词。","translation":"what 译“……的（东西/事）”；whether 译“是否”；that 不译，直接按陈述句译。"},
{"key":"subject-clause","label":"主语从句（That / Whether / What 置于句首）","definition":"放在句首充当主语的从句，谓语通常用单数，也可用 it 作形式主语把它后置。","identify":"句首出现 That / Whether / What 引导的完整从句，后面接主句谓语。","usage":"结构：That/Whether/What + 主语 + 谓语 + 主句谓语（单数）。that 不作成分、不译；whether 表“是否”；what 作成分。主语从句较长时常用 It is … that … 后置，避免头重脚轻。","translate":"译成“……这件事/这一做法”，再接“是/取决于/很重要”；不要译成“那个”。","trap":{"wrong":"Whether he will come are still unknown.","right":"Whether he will come is still unknown.","note":"主语从句整体视为单数，谓语要用 is；即使从句里出现复数名词也一样。"},"examples":[{"en":"Whether the experiment will succeed still remains uncertain.","zh":"实验是否会成功仍不确定。"},{"en":"What caused the accident is still under investigation.","zh":"造成事故的原因仍在调查中。"},{"en":"That she refused the offer surprised her colleagues.","zh":"她拒绝了这份工作，这让同事们很意外。"}],"understanding":"放在句首充当主语的从句，谓语通常用单数，也可用 it 作形式主语把它后置。","translation":"译成“……这件事/这一做法”，再接“是/取决于/很重要”；不要译成“那个”。"},
{"key":"predicative-clause","label":"表语从句（The reason is that …）","definition":"放在 be、seem、remain 等系动词后作表语的从句，用来说明主语是什么。","identify":"系动词（is/was/seems/remains）后面直接跟 that / whether / what / why 等引导的完整从句。","usage":"结构：主语 + be + that/whether/what + 从句。that 不作成分、不译；whether 表“是否”；what 作成分。The reason is that … 是固定表达，不用 because。","translate":"译成“是……/在于……”；that 不译，whether 译“是否”，what 译“……的东西”。","trap":{"wrong":"The reason why he left is because he was ill.","right":"The reason why he left is that he was ill.","note":"The reason is that … 是固定搭配；is because 把原因状语当表语，正式写作中算错。"},"examples":[{"en":"The problem is that nobody wants to take responsibility.","zh":"问题在于没有人愿意承担责任。"},{"en":"What matters most is whether we can work together.","zh":"最重要的是我们能否合作。"},{"en":"The question remains how we should raise the money.","zh":"问题仍然是我们该如何筹钱。"}],"understanding":"放在 be、seem、remain 等系动词后作表语的从句，用来说明主语是什么。","translation":"译成“是……/在于……”；that 不译，whether 译“是否”，what 译“……的东西”。"},
{"key":"wh-ever","label":"wh-ever 引导的让步/名词性从句","definition":"whoever、whatever、whenever 等词可引导名词性从句，也可引导让步状语从句。","identify":"看 wh-ever 在句中的位置和成分：作主语、宾语或表语就是名词性从句；作状语、能换成 no matter + wh- 就是让步从句。","usage":"名词性从句：Whoever comes is welcome.；让步从句：Whatever you say, I won't change my mind.。能换成 no matter + wh- 的是让步，不能换的是名词性从句。","translate":"名词性从句译“任何……的人/事”；让步从句译“无论……都……”。","trap":{"wrong":"Whatever you do, but don't give up.","right":"Whatever you do, don't give up.","note":"wh-ever 让步从句后面主句不能再加 but，中文的“但是”不能直译。"},"examples":[{"en":"Whoever finishes first will receive a small prize.","zh":"无论谁先完成，都会得到一个小奖品。"},{"en":"Whatever the outcome is, we must stay calm.","zh":"无论结果如何，我们都必须保持冷静。"},{"en":"Whenever she visits, she always brings homemade cookies.","zh":"她每次来访都会带自制饼干。"}],"understanding":"whoever、whatever、whenever 等词可引导名词性从句，也可引导让步状语从句。","translation":"名词性从句译“任何……的人/事”；让步从句译“无论……都……”。"},
{"key":"appositive","label":"同位语从句（the fact / idea / belief that …）","definition":"跟在 fact、idea、belief 等抽象名词后、说明其具体内容的从句，that 不作成分。","identify":"抽象名词（fact/idea/belief/news/evidence）后紧跟 that 从句，从句结构完整，that 不充当主语或宾语。","usage":"结构：抽象名词 + that + 完整从句。判断：that 在从句中不作成分，且从句内容等于该名词的内容，就是同位语从句；若 that 作成分，则是定语从句。","translate":"译成“……的事实/观点/证据是……”，或用冒号直接引出内容，that 不译。","trap":{"wrong":"The fact which he lied made everyone angry.","right":"The fact that he lied made everyone angry.","note":"从句结构完整、that 不作成分，是同位语从句，不能用 which。"},"examples":[{"en":"The idea that machines can think frightens some people.","zh":"机器能思考这一想法让一些人感到害怕。"},{"en":"There is little evidence that the drug is effective.","zh":"几乎没有证据表明这种药有效。"},{"en":"She rejected the suggestion that the meeting be postponed.","zh":"她拒绝了推迟会议的建议。"}],"understanding":"跟在 fact、idea、belief 等抽象名词后、说明其具体内容的从句，that 不作成分。","translation":"译成“……的事实/观点/证据是……”，或用冒号直接引出内容，that 不译。"},
{"key":"noun-appositive","label":"名词短语同位语（, a process called …）","definition":"用逗号隔开的另一个名词短语，对前面的名词作补充说明，二者指同一事物。","identify":"名词后出现逗号，再接一个名词短语（常带 a/an、the、called、known as），删掉后句子仍然完整。","usage":"结构：名词, + 名词短语, + 其余部分。常见形式：, a process called …、, an approach known as …。它没有引导词、没有谓语，只是换个说法解释前面的词。","translate":"译成“即……”“也就是……”，或用破折号、括号补出说明，不必译成完整句子。","trap":{"wrong":"Beijing, the capital of China, it has a long history.","right":"Beijing, the capital of China, has a long history.","note":"同位语只是名词短语，不能再用 it 重复指代主语，否则主语重复。"},"examples":[{"en":"The river, a major source of drinking water, is now polluted.","zh":"这条河是主要的饮用水源，如今已被污染。"},{"en":"They adopted a new method, an approach called peer review.","zh":"他们采用了一种新方法，即一种名为同行评审的做法。"},{"en":"Shanghai, the largest city in China, attracts millions of visitors.","zh":"上海是中国最大的城市，吸引了数百万游客。"}],"understanding":"用逗号隔开的另一个名词短语，对前面的名词作补充说明，二者指同一事物。","translation":"译成“即……”“也就是……”，或用破折号、括号补出说明，不必译成完整句子。"},
{"key":"parenthetical","label":"插入语（however / therefore / for example 等独立成分）","definition":"用逗号隔开的独立成分，表达说话人的态度或补充说明，去掉后句子仍然完整。","identify":"句中或句首出现 however、therefore、for example、in fact 等，前后常有逗号，不充当句子成分。","usage":"常见位置：句首加逗号；句中前后各一个逗号；句末前加逗号。however 表转折，therefore 表结果，for example 举例，in fact 表强调。插入语不影响主句结构和主谓一致，阅读时可先跳过。","translate":"分别译“然而/因此/例如/事实上/当然”，一般放在句首，用逗号隔开。","trap":{"wrong":"He didn't study hard, therefore he failed the exam.","right":"He didn't study hard; therefore, he failed the exam.","note":"therefore 是副词，不能像连词那样连接两个句子，需用分号或句号。"},"examples":[{"en":"The plan, however, was rejected by the committee.","zh":"然而，这个计划被委员会否决了。"},{"en":"She therefore decided to change her major last year.","zh":"因此，她去年决定转专业。"},{"en":"For example, many students study late into the night.","zh":"例如，许多学生学到深夜。"}],"understanding":"用逗号隔开的独立成分，表达说话人的态度或补充说明，去掉后句子仍然完整。","translation":"分别译“然而/因此/例如/事实上/当然”，一般放在句首，用逗号隔开。"},
{"key":"dash-parenthesis","label":"破折号插入语（— 补充说明 —）","definition":"用一对破折号插入的补充说明，作用类似括号，但语气更强调、更口语化。","identify":"句中突然出现单个或成对的破折号，中间是一段可删除的说明、举例或转折，删后句子仍通顺。","usage":"结构：主句 — 补充内容 — 主句剩余部分。破折号可代替逗号或括号，强调补充信息；正式写作中不宜过多。若插入内容本身有逗号，用破折号更清楚。翻译时用破折号或括号保留。","translate":"译成“——……——”或“……（即……）”，补充说明放在被说明内容之后。","trap":{"wrong":"The plan — which was costly, was rejected.","right":"The plan — which was costly — was rejected.","note":"破折号插入语必须成对使用，前后各一个；只写一个会把主句结构切断，句子就不完整了。"},"examples":[{"en":"The solution — a simple change in policy — worked almost immediately.","zh":"解决办法——政策上的一个简单改变——几乎立刻见效了。"},{"en":"He gave one reason — lack of time — for missing the deadline.","zh":"他为错过截止日期给出了一个理由——时间不够。"},{"en":"The old bridge — built in 1920 — is still in use.","zh":"这座旧桥建于 1920 年，至今仍在使用。"}],"understanding":"用一对破折号插入的补充说明，作用类似括号，但语气更强调、更口语化。","translation":"译成“——……——”或“……（即……）”，补充说明放在被说明内容之后。"},
{"key":"time-clause","label":"时间状语从句（when / while / before / after / once）","definition":"说明主句动作发生时间的从句，由 when、while、before 等连词引导。","identify":"主句前后出现 when/while/before/after/once/until 等连词，后面接完整的主谓结构，回答“什么时候”。","usage":"when 指某一点或某一段时间；while 强调“在……期间”，常接进行时；before/after 表示先后；once 表示“一旦”。时间从句中不能用 will 表将来，要用一般现在时代替。","translate":"译成“当……时/在……期间/在……之前/之后/一旦……”，中文习惯把时间从句放前面。","trap":{"wrong":"When he will arrive, we will start the meeting.","right":"When he arrives, we will start the meeting.","note":"时间状语从句不能用 will 表示将来，要用一般现在时替代，主句才用 will。"},"examples":[{"en":"While she was preparing dinner, the phone rang twice.","zh":"她在准备晚饭时，电话响了两次。"},{"en":"Once you start the program, it cannot be stopped.","zh":"一旦启动这个程序，就无法停止。"},{"en":"We had finished the report before the manager arrived.","zh":"经理到达之前，我们已经完成了报告。"}],"understanding":"说明主句动作发生时间的从句，由 when、while、before 等连词引导。","translation":"译成“当……时/在……期间/在……之前/之后/一旦……”，中文习惯把时间从句放前面。"},
{"key":"as-soon-as","label":"as soon as / the moment 一……就……","definition":"表示两个动作紧接发生的连词结构，as soon as 最常用，the moment 更书面。","identify":"看到 as soon as、the moment、the instant、immediately 等，后面接完整从句，主句表示紧接着的动作。","usage":"结构：As soon as + 从句（一般现在时）, 主句（将来时/过去时）。从句不能用 will。the moment 直接当连词。hardly … when 也表“一……就”，但主句要倒装并用过去完成时。","translate":"译成“一……就……”，先发生的动作放前面，后发生的放后面，不必逐字对应。","trap":{"wrong":"As soon as he will come, I will tell him the news.","right":"As soon as he comes, I will tell him the news.","note":"as soon as 从句用一般现在时表将来，不能用 will。"},"examples":[{"en":"As soon as the bell rang, the students left the classroom.","zh":"铃声一响，学生们就离开了教室。"},{"en":"The moment she saw the letter, she burst into tears.","zh":"她一看到那封信就哭了。"},{"en":"We will start as soon as everyone arrives.","zh":"大家一到，我们就开始。"}],"understanding":"表示两个动作紧接发生的连词结构，as soon as 最常用，the moment 更书面。","translation":"译成“一……就……”，先发生的动作放前面，后发生的放后面，不必逐字对应。"},
{"key":"reason-clause","label":"原因状语从句（because / since / now that）","definition":"说明主句动作原因的从句，由 because、since、as、now that 等连词引导。","identify":"主句后（或前）出现 because/since/as/now that，后面接完整主谓结构，回答“为什么”。","usage":"because 语气最强，回答 why；since/now that 表示已知原因，译“既然”；as 语气较弱。for 是并列连词，不能放句首。中文“因为……所以”不能同时译成 because … so。","translate":"because 译“因为”，since/now that 译“既然”，as 译“由于”；主句前不要再加“所以”。","trap":{"wrong":"Because he was tired, so he went to bed early.","right":"Because he was tired, he went to bed early.","note":"英语中 because 和 so 不能连用，中文的“因为……所以”只能译一个。"},"examples":[{"en":"She stayed home because the roads were covered with ice.","zh":"她待在家里，因为道路结了冰。"},{"en":"Since you already know the answer, why ask me?","zh":"既然你已经知道答案，为什么还问我？"},{"en":"Now that the exam is over, we can relax a little.","zh":"既然考试结束了，我们可以放松一下。"}],"understanding":"说明主句动作原因的从句，由 because、since、as、now that 等连词引导。","translation":"because 译“因为”，since/now that 译“既然”，as 译“由于”；主句前不要再加“所以”。"},
{"key":"reason-that","label":"The reason why … is that …","definition":"解释原因时的固定句型：先提出结果或原因，再用 that 从句给出具体理由。","identify":"看到 The reason why … is that …，注意最后用 that 而不用 because。","usage":"结构：The reason why + 从句 + is that + 原因。不能说 The reason is because …，因为 because 从句是状语，不能作表语。","translate":"译成“……的原因是……”，也可译“之所以……，是因为……”，语气更自然。","trap":{"wrong":"The reason why she was late is because her car broke down.","right":"The reason why she was late is that her car broke down.","note":"is 后面是表语从句，要用 that；because 只能引导原因状语从句。"},"examples":[{"en":"The reason why the plan failed is that nobody followed it.","zh":"计划失败的原因在于没有人照着执行。"},{"en":"The reason for his silence was that he disagreed completely.","zh":"他沉默的原因是他完全不同意。"},{"en":"That is the reason why she refused the offer.","zh":"这就是她拒绝这个提议的原因。"}],"understanding":"解释原因时的固定句型：先提出结果或原因，再用 that 从句给出具体理由。","translation":"译成“……的原因是……”，也可译“之所以……，是因为……”，语气更自然。"},
{"key":"condition-clause","label":"on condition that / provided that / as long as","definition":"表示“只有在……条件下才”的正式条件表达，语气比 if 更强、更明确。","identify":"看到 on condition that、provided that、as long as、only if，后面接完整从句，主句给出结果。","usage":"on condition that 意为“条件是”，多用于正式文体；provided that 意为“只要”；as long as 同义但更口语。它们都直接接从句。only if 放句首时主句要倒装。","translate":"统一译“只要/条件是/只有在……条件下”，从句放前面，主句用“就/才”。","trap":{"wrong":"You may go out on condition that you will come back by ten.","right":"You may go out on condition that you come back by ten.","note":"条件从句用一般现在时表将来，不用 will，主句才用情态动词或将来时。"},"examples":[{"en":"You can use the car on condition that you drive carefully.","zh":"你可以用这辆车，条件是小心驾驶。"},{"en":"Provided that the weather is fine, the match will go ahead.","zh":"只要天气好，比赛就会照常进行。"},{"en":"You may keep the book as long as you return it.","zh":"只要你归还，就可以留着这本书。"}],"understanding":"表示“只有在……条件下才”的正式条件表达，语气比 if 更强、更明确。","translation":"统一译“只要/条件是/只有在……条件下”，从句放前面，主句用“就/才”。"},
{"key":"conditional-clause","label":"条件状语从句（unless / provided that / in case）","definition":"表示“如果、除非、以防”等条件的从句，用 unless、if、in case 等引导。","identify":"主句前后出现 if/unless/in case/provided that，后面接完整从句；从句用一般现在时表将来。","usage":"unless = if not，本身含否定，主句不能再加 not；in case 表示“以防万一”，从句常用一般现在时或 should；provided that 表示“只要”。条件从句同样不用 will 表将来，主句才用将来时或情态动词。","translate":"unless 译“除非……否则”；in case 译“以防”；provided that 译“只要”。","trap":{"wrong":"Unless you don't hurry, you will miss the train.","right":"Unless you hurry, you will miss the train.","note":"unless 本身等于 if not，从句里再加 don't 就变成双重否定。"},"examples":[{"en":"Unless the government acts soon, prices will keep rising.","zh":"除非政府尽快采取行动，否则物价会持续上涨。"},{"en":"Take a taxi in case you are late for the interview.","zh":"打车去吧，以防面试迟到。"},{"en":"If it rains tomorrow, the trip will be cancelled.","zh":"如果明天下雨，旅行就会取消。"}],"understanding":"表示“如果、除非、以防”等条件的从句，用 unless、if、in case 等引导。","translation":"unless 译“除非……否则”；in case 译“以防”；provided that 译“只要”。"},
{"key":"concessive-clause","label":"让步状语从句（although / though / even if）","definition":"表示“虽然、即使”的从句，先承认一种情况，再说明主句的相反结果。","identify":"出现 although/though/even though/even if/while，后面接完整从句；主句前不能再加 but。","usage":"although 偏事实，even if 偏假设；though 还可放句末作副词。主句不能用 but，但可用 yet/still。while 也可表让步，译“虽然”。","translate":"译成“虽然……但……”“即使……也……”，中文可保留“但/也”，英文不能加 but。","trap":{"wrong":"Although he was tired, but he kept working.","right":"Although he was tired, he kept working.","note":"although 引导从句后，主句不能再加 but；中文的“虽然……但是”在英文里只能留一个。"},"examples":[{"en":"Although the evidence was weak, the jury convicted him.","zh":"尽管证据不足，陪审团还是判他有罪。"},{"en":"Even if the plan fails, we will learn something useful.","zh":"即使计划失败，我们也会学到有用的东西。"},{"en":"Though it was raining heavily, they continued the game.","zh":"虽然雨下得很大，他们还是继续比赛。"}],"understanding":"表示“虽然、即使”的从句，先承认一种情况，再说明主句的相反结果。","translation":"译成“虽然……但……”“即使……也……”，中文可保留“但/也”，英文不能加 but。"},
{"key":"as-concession","label":"as 引导让步倒装（Much as I like it）","definition":"as 表示“尽管”时必须倒装，把形容词、副词、名词或动词原形提到 as 前面。","identify":"句首出现形容词/副词/名词/动词原形 + as + 主语 + 谓语，且可换成 although，就是让步倒装。","usage":"adj./adv./n./v. + as + 主语 + 谓语。Much as I like it = Although I like it；Child as he is = Although he is a child（名词前不用冠词）。","translate":"译成“尽管……、虽然……”，绝不能译成“因为”或“当……时”。","trap":{"wrong":"As he is a child, he knows a lot about physics.","right":"Child as he is, he knows a lot about physics.","note":"表让步时须把表语提前并去掉冠词，形成 Child as he is 的倒装。"},"examples":[{"en":"Much as I respect him, I cannot accept his conclusion.","zh":"尽管我很尊敬他，但我无法接受他的结论。"},{"en":"Hard as she tried, she could not solve the problem.","zh":"尽管她很努力，还是解决不了这个问题。"},{"en":"Young as he is, he has already published two papers.","zh":"尽管他很年轻，他已经发表了两篇论文。"}],"understanding":"as 表示“尽管”时必须倒装，把形容词、副词、名词或动词原形提到 as 前面。","translation":"译成“尽管……、虽然……”，绝不能译成“因为”或“当……时”。"},
{"key":"concession-no-matter","label":"no matter how / however + 形容词 让步","definition":"用 no matter how 或 however 加形容词，表示“无论多么……”，引导让步从句。","identify":"看到 no matter how、however、whatever、whoever 等，后面紧跟形容词或副词，再接主语和谓语。","usage":"结构：No matter how + adj./adv. + 主语 + 谓语, 主句。however 同义，但后面必须紧跟形容词或副词，且用陈述语序，不能倒装。","translate":"译成“无论多么……都……”，注意 however 在这里不是“然而”，而是“无论怎么”。","trap":{"wrong":"No matter how hard did he try, he could not pass the test.","right":"No matter how hard he tried, he could not pass the test.","note":"no matter how 引导的从句用陈述语序，不能像疑问句那样倒装。"},"examples":[{"en":"No matter how late it is, she always finishes her work.","zh":"无论多晚，她总是把工作做完。"},{"en":"However difficult the task is, we must complete it.","zh":"无论任务多难，我们都必须完成。"},{"en":"No matter where you go, remember to call home.","zh":"无论你去哪里，记得给家里打电话。"}],"understanding":"用 no matter how 或 however 加形容词，表示“无论多么……”，引导让步从句。","translation":"译成“无论多么……都……”，注意 however 在这里不是“然而”，而是“无论怎么”。"},
{"key":"purpose-clause","label":"目的状语（so that / in order that / in order to）","definition":"说明做某事“为了什么”的从句或短语，常用 so that、in order to。","identify":"看到 so that / in order that + 从句，或 in order to + 动词原形，表示目的。","usage":"so that/in order that 从句常带 can/could/may/might；in order to/so as to 后接动词原形，否定用 in order not to。","translate":"译成“为了……”“以便……”，中文通常把目的放在主句前面，更符合表达习惯。","trap":{"wrong":"He got up early so that to catch the first bus.","right":"He got up early so as to catch the first bus.","note":"so that 后面必须接完整从句；接动词原形要用 so as to 或 in order to。"},"examples":[{"en":"She spoke slowly so that everyone could follow her.","zh":"她说得很慢，以便每个人都能跟上。"},{"en":"In order to save time, we took the express train.","zh":"为了节省时间，我们乘坐了特快列车。"},{"en":"The school added lights in order that students could study safely.","zh":"学校增加了照明，以便学生能安全地学习。"}],"understanding":"说明做某事“为了什么”的从句或短语，常用 so that、in order to。","translation":"译成“为了……”“以便……”，中文通常把目的放在主句前面，更符合表达习惯。"},
{"key":"purpose-lest","label":"lest / for fear that 虚拟目的从句","definition":"表示“以免、生怕”的正式结构，从句用 should + 动词原形，should 可以省略。","identify":"看到 lest 或 for fear that，后面接从句；lest 从句常用动词原形，for fear that 从句常用 should。","usage":"结构：主句 + lest + 主语 + (should) + 动词原形；或 for fear that + 主语 + should/might + 动词。lest 本身含否定，从句不能再加 not。","translate":"译成“以免……”“生怕……”，不要译成“因为害怕”，它表达的是目的。","trap":{"wrong":"Study hard lest you will fail the exam.","right":"Study hard lest you should fail the exam.","note":"lest 从句用 should + 动词原形，不用 will；should 也可省略。"},"examples":[{"en":"Take notes lest you forget the key points.","zh":"记笔记，以免忘记要点。"},{"en":"She spoke quietly for fear that someone might hear her.","zh":"她轻声说话，生怕有人听见。"},{"en":"He checked the data twice lest any error should remain.","zh":"他把数据核对了两遍，以免留下错误。"}],"understanding":"表示“以免、生怕”的正式结构，从句用 should + 动词原形，should 可以省略。","translation":"译成“以免……”“生怕……”，不要译成“因为害怕”，它表达的是目的。"},
{"key":"so-that","label":"so … that / such … that 结果状语从句","definition":"表示“如此……以至于……”的结果从句，so 修饰形容词或副词，such 修饰名词。","identify":"看到 so + 形容词/副词 + that，或 such + (a/an) + 形容词 + 名词 + that，that 后是结果。","usage":"so 后接 adj./adv.；such 后接名词短语。so many/much/few/little + 名词 + that 也用 so。so 或 such 提到句首时主句要倒装。","translate":"译成“如此……以至于……”，中文常简化为“……得让……”“太……结果……”。","trap":{"wrong":"It was so a difficult test that many students failed.","right":"It was such a difficult test that many students failed.","note":"difficult 修饰名词 test，应用 such a + 形容词 + 名词；so 只能直接修饰形容词。"},"examples":[{"en":"The box was so heavy that nobody could lift it.","zh":"箱子太重了，没人能搬动。"},{"en":"She is such a talented writer that publishers seek her out.","zh":"她是一位很有才华的作家，出版商都主动找她。"},{"en":"So convincing was his argument that everyone agreed.","zh":"他的论证如此有说服力，以至于大家都同意了。"}],"understanding":"表示“如此……以至于……”的结果从句，so 修饰形容词或副词，such 修饰名词。","translation":"译成“如此……以至于……”，中文常简化为“……得让……”“太……结果……”。"},
{"key":"while-contrast","label":"while / whereas 对比从句","definition":"用 while 或 whereas 连接两个相反或相对的事实，表示“而、然而”的对比。","identify":"两个分句用逗号隔开，while/whereas 位于第二个分句前，前后内容形成对照，可换成 but。","usage":"while 有三种用法：时间“当……时”、对比“而”、让步“虽然”；whereas 只表对比。判断：两个动作同时进行就是时间；两个事实相反就是对比。对比义的 while 不能放句首译成“当”。","translate":"对比义译“而、然而”；时间义译“当……时”；让步义译“虽然”，按上下文选定。","trap":{"wrong":"My brother likes tea, while my sister she prefers coffee.","right":"My brother likes tea, while my sister prefers coffee.","note":"while 从句里 my sister 已是主语，再加 she 就造成主语重复。"},"examples":[{"en":"Some students prefer group work, while others study better alone.","zh":"有些学生喜欢小组学习，而另一些学生独自学习效果更好。"},{"en":"The north is dry and cold, whereas the south is wet and warm.","zh":"北方干燥寒冷，而南方潮湿温暖。"},{"en":"While the plan looks simple, it is hard to carry out.","zh":"虽然这个计划看起来简单，却很难实施。"}],"understanding":"用 while 或 whereas 连接两个相反或相对的事实，表示“而、然而”的对比。","translation":"对比义译“而、然而”；时间义译“当……时”；让步义译“虽然”，按上下文选定。"},
{"key":"now-that","label":"now that / given that / seeing that 原因从句","definition":"表示“既然、考虑到”的原因从句，所给理由通常是听话人已知或显而易见的事实。","identify":"看到 now that、given that、seeing that 位于句首，后面接完整从句，主句给出结论或建议。","usage":"now that 强调“现在情况已变”，译“既然”；given that 译“考虑到”，given 后也可直接接名词；seeing that 译“既然、鉴于”。这些连词比 because 弱，通常不回答 why，也不用于强调句。","translate":"now that 译“既然”，given that 译“考虑到”，seeing that 译“鉴于、既然”。","trap":{"wrong":"Now that you are here, so we can start.","right":"Now that you are here, we can start.","note":"now that 已引导从句，主句不能再加 so，中英文连词不能成对直译。"},"examples":[{"en":"Now that you have finished the report, you can go home.","zh":"既然你完成了报告，就可以回家了。"},{"en":"Given that the data are incomplete, the conclusion is unreliable.","zh":"考虑到数据不完整，这个结论并不可靠。"},{"en":"Seeing that everyone agrees, we will adopt the proposal.","zh":"既然大家都同意，我们就采纳这个提议。"}],"understanding":"表示“既然、考虑到”的原因从句，所给理由通常是听话人已知或显而易见的事实。","translation":"now that 译“既然”，given that 译“考虑到”，seeing that 译“鉴于、既然”。"},
{"key":"as-long-as","label":"as long as 引导条件状语从句","definition":"as long as 表示“只要”，引导条件从句，相当于 provided that。","identify":"as long as 后接完整的主谓结构，且可换成 if，就是条件从句；若后接名词且表示长度，则是比较。","usage":"结构：As long as + 从句, 主句。从句用一般现在时表将来。它和 as … as 比较结构不同：条件义后面必须有主语和谓语，比较义后面只接名词或代词，如 as long as two meters。","translate":"条件义译“只要……就……”；比较义译“和……一样长”，两者要分清。","trap":{"wrong":"As long as you will study hard, you will pass the exam.","right":"As long as you study hard, you will pass the exam.","note":"条件状语从句用一般现在时表示将来，不用 will，主句才用 will。"},"examples":[{"en":"You can stay here as long as you keep the room clean.","zh":"只要你保持房间干净，就可以待在这里。"},{"en":"As long as the weather permits, we will hold the race.","zh":"只要天气允许，我们就举行比赛。"},{"en":"The rope is as long as three meters.","zh":"这根绳子有三米长。"}],"understanding":"as long as 表示“只要”，引导条件从句，相当于 provided that。","translation":"条件义译“只要……就……”；比较义译“和……一样长”，两者要分清。"},
{"key":"as-if","label":"as if / as though 引导方式状语从句","definition":"表示“好像、仿佛”的方式状语从句，可接陈述语气，也可接虚拟语气。","identify":"看到 as if / as though 后接完整从句，判断所说内容是否与事实相符，据此决定用陈述还是虚拟。","usage":"与事实相反用虚拟：as if + 过去式（现在）、had done（过去）；可能性较大用陈述语气。也可接 to do：He opened his mouth as if to speak。判断依据是“像不像真的”。","translate":"译成“好像……似的”，虚拟时加“仿佛、似乎”，不要译成“如果”。","trap":{"wrong":"He talks as if he has seen the film yesterday.","right":"He talks as if he had seen the film yesterday.","note":"yesterday 表明与过去事实相反，as if 从句要用 had done。"},"examples":[{"en":"She looked at me as if she had never seen me before.","zh":"她看着我，好像从没见过我似的。"},{"en":"It sounds as though the engine is failing.","zh":"听起来发动机好像要坏了。"},{"en":"He raised his hand as if to ask a question.","zh":"他举起手，好像要问问题。"}],"understanding":"表示“好像、仿佛”的方式状语从句，可接陈述语气，也可接虚拟语气。","translation":"译成“好像……似的”，虚拟时加“仿佛、似乎”，不要译成“如果”。"},
{"key":"as-phrase","label":"as 引出的固定短语（as well as / as a result / as for）","definition":"由 as 构成的固定短语，各有独立含义，不能一律按“作为”来理解。","identify":"看到 as well as、as a result、as for、as a whole、as a rule 等固定搭配，要把整个短语一起记。","usage":"as well as = 以及，连接并列成分，谓语与前面主语一致；as a result = 因此；as for = 至于；as a whole = 总体上；as opposed to = 与……相对。","translate":"按固定义译：“以及/因此/至于/总体上/通常/与……相对”，不要译“作为”。","trap":{"wrong":"The teacher as well as the students were invited.","right":"The teacher as well as the students was invited.","note":"as well as 连接主语时，谓语与前面的主语保持一致，这里核心是 teacher。"},"examples":[{"en":"The course covers writing as well as speaking.","zh":"这门课既包括写作也包括口语。"},{"en":"As a result, the company lost two important clients.","zh":"结果，公司失去了两个重要客户。"},{"en":"As for the price, we can discuss it later.","zh":"至于价格，我们可以稍后再谈。"}],"understanding":"由 as 构成的固定短语，各有独立含义，不能一律按“作为”来理解。","translation":"按固定义译：“以及/因此/至于/总体上/通常/与……相对”，不要译“作为”。"},
{"key":"as-time-cause","label":"as 引导时间/原因状语从句（随着；由于）","definition":"as 可引导时间从句表示“随着、当……时”，也可引导原因从句表示“由于”。","identify":"as 位于句首或逗号后，后接完整从句；看从句与主句是同时发生（时间），还是解释原因（原因）。","usage":"时间义强调两个动作同时或同步变化，常译“随着”；原因义语气比 because 弱，常译“由于”，多用于已知理由。判断：译“随着”读得通就是时间，读不通就改译“由于”；也可用 since/while 替换验证。","translate":"时间义译“随着、当……时”；原因义译“由于、因为”，根据句意选择，不要一律译“当……时”。","trap":{"wrong":"As he was ill, so he stayed at home.","right":"As he was ill, he stayed at home.","note":"as 引导原因从句时，主句不能再加 so，中英文不能成对直译。"},"examples":[{"en":"As the sun rose, the fog slowly disappeared.","zh":"随着太阳升起，雾气慢慢散去。"},{"en":"As the deadline approaches, the team works longer hours.","zh":"随着截止日期临近，团队工作的时间更长了。"},{"en":"As she had no money, she walked home.","zh":"由于没有钱，她走回了家。"}],"understanding":"as 可引导时间从句表示“随着、当……时”，也可引导原因从句表示“由于”。","translation":"时间义译“随着、当……时”；原因义译“由于、因为”，根据句意选择，不要一律译“当……时”。"},
{"key":"as-many-as","label":"as many / much … as 同级比较（含省略）","definition":"as many/much + 名词 + as 表示两边数量一样多，用来把两个数量放在一起比较。","identify":"句中先出现 as many 或 as much，后面再接一个 as；第二个 as 后常只剩名词或代词，被省掉的谓语要自己补回。","usage":"结构为 as many + 可数名词复数 + as，或 as much + 不可数名词 + as。第二个 as 后面接比较对象；谓语与前文重复时可以省略，只留主语，如 as many books as he does。倍数词要放在第一个 as 前面，如 twice as many as。","translate":"译成“和……一样多”“达到……的数量”。half as many as 译“是……的一半”，twice as many as 译“是……的两倍”。","trap":{"wrong":"The company hired as many engineers than it did last year.","right":"The company hired as many engineers as it did last year.","note":"同级比较的第二部分只能用 as，不能换成 than；than 只能跟比较级搭配使用。"},"examples":[{"en":"She spends as much time on reading as her brother does.","zh":"她花在阅读上的时间和她弟弟一样多。"},{"en":"We produced twice as many cars this year as we did in 2020.","zh":"我们今年生产的汽车是 2020 年的两倍。"}],"understanding":"as many/much + 名词 + as 表示两边数量一样多，用来把两个数量放在一起比较。","translation":"译成“和……一样多”“达到……的数量”。half as many as 译“是……的一半”，twice as many as 译“是……的两倍”。"},
{"key":"the-more","label":"the more …, the more … 比较句式","definition":"两个 the + 比较级前后呼应，前一句是条件，后一句是结果，表示一方变化引起另一方变化。","identify":"句首或分句开头出现 the + 比较级，逗号后还有 the + 比较级，两半各有一套主谓，就是“越……越……”。","usage":"公式：The + 比较级 + 主语 + 谓语, the + 比较级 + 主语 + 谓语。前一个 the 引条件，后一个 the 引结果，顺序不能颠倒。比较级可以带名词，如 the more books you read；谓语有时可省，如 the sooner, the better。","translate":"译成“越……，就越……”。前半句用“越……”，后半句用“就越……”，中文习惯条件在前、结果在后。","trap":{"wrong":"More you read, more you know.","right":"The more you read, the more you know.","note":"两个比较级前面都必须有 the，缺了 the 就不成这个句式，句子也读不通。"},"examples":[{"en":"The more carefully you plan, the fewer mistakes you will make.","zh":"计划得越仔细，犯的错误就越少。"},{"en":"The longer the meeting lasted, the less attention people paid.","zh":"会议开得越久，人们越不专心。"},{"en":"The more books you read, the wider your horizons become.","zh":"你读的书越多，眼界就越宽。"}],"understanding":"两个 the + 比较级前后呼应，前一句是条件，后一句是结果，表示一方变化引起另一方变化。","translation":"译成“越……，就越……”。前半句用“越……”，后半句用“就越……”，中文习惯条件在前、结果在后。"},
{"key":"comparative-than","label":"比较级 + than 结构（含 than 后省略）","definition":"用形容词或副词的比较级加 than，把两个对象放在一起比高低，than 后面是比较对象。","identify":"看到 -er 或 more/less/fewer + 形容词，后面紧跟 than，就是比较级结构；than 后常只剩一个名词或代词。","usage":"结构：A + 比较级 + than + B。短词加 -er，长词用 more + 原级，两者不能叠用。than 后重复的谓语可省略，只留比较对象，如 than his brother does。than 后接代词时口语常用宾格，正式写作可用主格。","translate":"译成“比……更……”。less … than 译“不如……”，more than 常译“不止、超过”，not more than 译“不超过”。","trap":{"wrong":"This method is much more better than the old one.","right":"This method is much better than the old one.","note":"more 和 -er 不能叠用，better 本身已经是比较级，前面不能再加 more，也不能加 most。"},"examples":[{"en":"The new policy proved far more effective than the previous one.","zh":"新政策被证明比原来那条有效得多。"},{"en":"Fewer students failed the exam than the teacher had expected.","zh":"考试不及格的学生比老师预想的少。"}],"understanding":"用形容词或副词的比较级加 than，把两个对象放在一起比高低，than 后面是比较对象。","translation":"译成“比……更……”。less … than 译“不如……”，more than 常译“不止、超过”，not more than 译“不超过”。"},
{"key":"comparative-substitute","label":"比较从句的替代（as / than + 主语 + do / did）","definition":"比较从句里用 do/does/did 代替前面重复的动词，免得把同一个谓语写两遍。","identify":"as 或 than 后面出现“主语 + do/did”，后面再没有别的动词，说明动词被替代了，要回到前半句找原动词。","usage":"前半句是实义动词，后半句用 do/does/did 替代：She reads faster than I do。前半句有情态动词或 be 动词时，保留 can、will、is，如 than I can、than he is。时态跟着前半句走：过去用 did，现在用 do 或 does。","translate":"译成“和……一样……”“比……更……”，替代的 do/did 不必译出，只要把比较对象说清楚。","trap":{"wrong":"She reads faster than I am.","right":"She reads faster than I do.","note":"前半句谓语是实义动词 reads，替代词要用 do 的相应形式，不能用 be 动词。"},"examples":[{"en":"The company hired more workers this year than it did last year.","zh":"这家公司今年招的工人比去年多。"},{"en":"He speaks English as fluently as his teacher does.","zh":"他英语说得和他老师一样流利。"}],"understanding":"比较从句里用 do/does/did 代替前面重复的动词，免得把同一个谓语写两遍。","translation":"译成“和……一样……”“比……更……”，替代的 do/did 不必译出，只要把比较对象说清楚。"},
{"key":"as-as-comparison","label":"as … as 同级比较（形容词/副词原级）","definition":"as + 形容词或副词原级 + as，表示两者在某一性质上程度相同，是最常见的同级比较。","identify":"两个 as 成对出现，中间夹着形容词或副词，而且必须是原级；否定形式是 not as … as，中间同样用原级。","usage":"结构：A + be 动词/实义动词 + as + 形容词/副词原级 + as + B。形容词原级作表语，副词原级修饰动词。not as … as 意为“不如……”。第二个 as 后重复的谓语可省略，只留比较对象。","translate":"译成“和……一样……”，否定式译“不如……”。不要把它译成“不一样”，那是误解。","trap":{"wrong":"This test is as harder as the last one.","right":"This test is as hard as the last one.","note":"as … as 中间必须用原级，比较级 harder 不能放进来，这是最常见的错误。"},"examples":[{"en":"The second test was as difficult as the first one.","zh":"第二次考试和第一次一样难。"},{"en":"She finished the report as quickly as her colleague did.","zh":"她完成报告的速度和同事一样快。"}],"understanding":"as + 形容词或副词原级 + as，表示两者在某一性质上程度相同，是最常见的同级比较。","translation":"译成“和……一样……”，否定式译“不如……”。不要把它译成“不一样”，那是误解。"},
{"key":"not-so-much-as","label":"not so much A as B（与其说 A 不如说 B）","definition":"not so much A as B 表示前后两项中后者才真正成立，前者只是表面的说法，重点在 B。","identify":"句中同时出现 not so much 和 as，A、B 多为名词、形容词或短语，形成对照，重心落在 as 后面的 B 上。","usage":"结构：not so much A as B，A 和 B 的形式要对等。意思为“与其说 A，不如说 B”，B 才是重点。不要与 not as much … as（数量不如）混淆：前者比性质，后者比数量，可看 as 前有没有 many/much 修饰名词。","translate":"译成“与其说 A，不如说 B”。重点在后半句，翻译时把 B 说得更重。","trap":{"wrong":"He is not so much a writer than a journalist.","right":"He is not so much a writer as a journalist.","note":"这个句式固定用 as 连接两项，换成 than 就变成比较级结构，意思也说不通。"},"examples":[{"en":"The failure was not so much a matter of money as of timing.","zh":"这次失败与其说是钱的问题，不如说是时机的问题。"},{"en":"She was not so much angry as disappointed at the result.","zh":"对这个结果，她与其说生气，不如说失望。"}],"understanding":"not so much A as B 表示前后两项中后者才真正成立，前者只是表面的说法，重点在 B。","translation":"译成“与其说 A，不如说 B”。重点在后半句，翻译时把 B 说得更重。"},
{"key":"comparative-degree","label":"比较级修饰与最高级（much / far / the most…）","definition":"比较级前可用 much、far、a lot 等词加强程度，最高级前一般加 the，表示三者以上中的极点。","identify":"比较级前出现 much、far、a lot、a little、even、still，或最高级前有 the、one of the，就是在加强程度或限定范围。","usage":"修饰比较级只能用 much、far、a lot、a bit、a little、even、still，不能用 very。最高级前一般加 the，副词最高级可省 the。one of the + 最高级 + 复数名词表示“最……之一”。the + 比较级也可指两者中较……的那个。","translate":"much、far + 比较级译“得多、远远”；最高级译“最……”；one of the 最高级译“最……之一”。","trap":{"wrong":"This problem is very more difficult than that one.","right":"This problem is much more difficult than that one.","note":"very 不能修饰比较级，表示“难得多”要用 much 或 far，这是固定搭配，不能随意替换。"},"examples":[{"en":"The second half of the film is far more interesting than the first.","zh":"影片后半部分比前半部分有趣得多。"},{"en":"She is one of the most experienced teachers in the school.","zh":"她是学校里最有经验的老师之一。"}],"understanding":"比较级前可用 much、far、a lot 等词加强程度，最高级前一般加 the，表示三者以上中的极点。","translation":"much、far + 比较级译“得多、远远”；最高级译“最……”；one of the 最高级译“最……之一”。"},
{"key":"times-comparison","label":"倍数表达（three times as … as / the size of）","definition":"用 twice、three times 等倍数词说明一方是另一方的几倍，常用于数据、规模和趋势。","identify":"句中同时出现倍数词（twice、three times、double），又出现 as … as、the size/length of 或比较级，说明在比较两方的倍数关系。","usage":"三种常用结构：倍数 + as + 原级 + as（three times as large as）；倍数 + the + size/length/weight + of（three times the size of）；倍数 + 比较级 + than（three times larger than）。都表示“是……的三倍”，不是“大三倍”。第三种含义有争议，写作时前两种最清楚。","translate":"译成“是……的几倍”。twice 译“两倍”，three times 译“三倍”，不要译成“多了几倍”。","trap":{"wrong":"The new hall is three times as larger as the old one.","right":"The new hall is three times as large as the old one.","note":"as … as 中间要用原级，large 不能写成比较级 larger，倍数词应放在最前面。"},"examples":[{"en":"The new bridge is three times as long as the old one.","zh":"新桥的长度是旧桥的三倍。"},{"en":"Their output is now four times the level of ten years ago.","zh":"他们现在的产量是十年前的四倍。"}],"understanding":"用 twice、three times 等倍数词说明一方是另一方的几倍，常用于数据、规模和趋势。","translation":"译成“是……的几倍”。twice 译“两倍”，three times 译“三倍”，不要译成“多了几倍”。"},
{"key":"compared-with","label":"compared with / compared to 比较短语","definition":"compared with 或 compared to 是过去分词短语，放在句首或句尾，用来引出被比较的另一方。","identify":"句首或句末出现 compared with、compared to、in comparison with，后面接名词，前面是主句，中间用逗号隔开，就是比较短语。","usage":"compared with 与 compared to 现代英语基本通用，都表示“与……相比”。它修饰整个句子，逻辑主语要和主句主语一致，否则成悬垂结构。放句首时后面加逗号。不要与主动形式的 comparing 混用。","translate":"译成“与……相比”“比起……来”。中文通常把这个短语放在句首。","trap":{"wrong":"Comparing with last year, sales have risen sharply.","right":"Compared with last year, sales have risen sharply.","note":"销售额是被比较的对象，要用过去分词 compared 表示被动，不能用主动的 comparing。"},"examples":[{"en":"Compared with last year, the number of applicants has doubled.","zh":"与去年相比，申请人数翻了一番。"},{"en":"The cost of living here is still low compared to other cities.","zh":"与其它城市相比，这里的生活成本仍然较低。"}],"understanding":"compared with 或 compared to 是过去分词短语，放在句首或句尾，用来引出被比较的另一方。","translation":"译成“与……相比”“比起……来”。中文通常把这个短语放在句首。"},
{"key":"comparative-separated","label":"被介词短语隔开的比较（less important for A than for B）","definition":"比较级和 than 之间插入介词短语等成分，两个比较对象分别跟在同一个介词后面。","identify":"看到比较级后先出现一个介词短语，之后才出现 than，且 than 后重复同一介词，说明比较对象被隔开了。","usage":"结构：比较级 + 介词短语 + than + 同一介词 + 另一对象。理解时先把介词短语分别挂到两边：less important for A than for B 意为“对 A 来说不如对 B 重要”。than 后不能漏掉介词，否则比较对象不清楚。","translate":"译成“对 A 来说不如对 B……”。中文要把两个对象各自跟介词的搭配说清楚，不要合成一句模糊的话。","trap":{"wrong":"The rule is less important for adults than children.","right":"The rule is less important for adults than for children.","note":"than 后面要重复介词 for，否则 children 会被读成与 adults 并列，比较对象就乱了。"},"examples":[{"en":"The change is more significant for small firms than for large ones.","zh":"这一变化对小公司来说比对大公司更重要。"},{"en":"This skill is less useful for beginners than for advanced learners.","zh":"这项技能对初学者不如对进阶学习者有用。"}],"understanding":"比较级和 than 之间插入介词短语等成分，两个比较对象分别跟在同一个介词后面。","translation":"译成“对 A 来说不如对 B……”。中文要把两个对象各自跟介词的搭配说清楚，不要合成一句模糊的话。"},
{"key":"cleft","label":"强调句 It is … that …","definition":"用 It is 或 It was … that … 把句中某一成分提到前面加以突出，其余部分保持原序。","identify":"句首是 It is 或 It was，后面接一个名词、时间或地点，再有 that/who，去掉这两部分后剩下的仍是完整句子。","usage":"判断方法：去掉 It is/was 和 that，剩下部分能独立成句就是强调句；不能成句则可能是主语从句或定语从句。强调人时 that 可换成 who，强调其他成分一律用 that。被强调部分作主语时，that 后的谓语与它保持一致。","translate":"译成“正是……才……”“是……的”。中文常用“正是、就是”把重点提出来，不要译成“它是……的”。","trap":{"wrong":"It was in 2019 when the company was founded.","right":"It was in 2019 that the company was founded.","note":"强调时间状语时连接词仍用 that，不能因为指时间就换成 when，这是强调句的固定形式。"},"examples":[{"en":"It was his attitude that impressed the interviewer most.","zh":"最打动面试官的是他的态度。"},{"en":"It is through practice that skills are gradually built.","zh":"技能正是通过练习逐步建立起来的。"}],"understanding":"用 It is 或 It was … that … 把句中某一成分提到前面加以突出，其余部分保持原序。","translation":"译成“正是……才……”“是……的”。中文常用“正是、就是”把重点提出来，不要译成“它是……的”。"},
{"key":"inversion","label":"部分倒装（否定词 / only 置于句首）","definition":"否定词或 only + 状语放到句首时，只把助动词、情态动词或 be 提到主语前，实义动词不动。","identify":"句首出现 never、seldom、hardly、not until、no sooner、only + 状语等，后面是“助动词 + 主语 + 动词”，就是部分倒装。","usage":"部分倒装只提前助动词：Never have I seen it；Only then did he realize it。原句没有助动词时补 do/does/did，实义动词位置不变。hardly … when 与 no sooner … than 中，主句用过去完成时，从句用一般过去时。only 修饰主语时不倒装。","translate":"按正常语序理解，译成“直到……才”“一……就……”“只有……才……”。倒装本身不改变意思。","trap":{"wrong":"Never I have seen such a convincing argument.","right":"Never have I seen such a convincing argument.","note":"否定词置于句首必须部分倒装，助动词 have 要提到主语 I 前面，实义动词 seen 留在原位。"},"examples":[{"en":"Seldom does the manager change his mind once a decision is made.","zh":"一旦做出决定，经理很少改变主意。"},{"en":"Hardly had the meeting begun when the power went out.","zh":"会议刚开始，电就停了。"}],"understanding":"否定词或 only + 状语放到句首时，只把助动词、情态动词或 be 提到主语前，实义动词不动。","translation":"按正常语序理解，译成“直到……才”“一……就……”“只有……才……”。倒装本身不改变意思。"},
{"key":"so-neither-inversion","label":"so / neither 倒装（So did he）","definition":"so 或 neither/nor 放句首表示“也是如此”或“也不如此”，后面用倒装，助动词与前句一致。","identify":"逗号后出现 and so + 助动词 + 主语，或 and neither/nor + 助动词 + 主语，说明在回应前一句的肯定或否定。","usage":"前句肯定，用 so + 助动词 + 主语；前句否定，用 neither 或 nor + 助动词 + 主语。助动词要与前句时态、情态一致：likes 用 does，can 用 can，has 用 has。主语必须换成新的名词或代词，不能重复原主语。","translate":"译成“……也是这样”“……也不……”。neither 不要译成“两者都不”，so 也不要译成“所以”。","trap":{"wrong":"She enjoyed the lecture, and so her classmates did.","right":"She enjoyed the lecture, and so did her classmates.","note":"so 置于句首要倒装，助动词 did 应放在主语 her classmates 之前，不能按陈述语序写。"},"examples":[{"en":"He cannot attend the meeting, and neither can I.","zh":"他不能参加这个会议，我也不能。"},{"en":"They finished the project ahead of time, and so did we.","zh":"他们提前完成了项目，我们也一样。"}],"understanding":"so 或 neither/nor 放句首表示“也是如此”或“也不如此”，后面用倒装，助动词与前句一致。","translation":"译成“……也是这样”“……也不……”。neither 不要译成“两者都不”，so 也不要译成“所以”。"},
{"key":"emphatic-do","label":"do / does / did + 动词原形（强调）","definition":"在动词原形前加 do/does/did 来强调肯定语气，意为“确实、的确”，时态和数由 do 体现。","identify":"句中 do/does/did 后面紧跟动词原形，且这个 do 既不是实义动词也不是替代词，就是在起强调作用。","usage":"结构：do/does/did + 动词原形。现在时第三人称单数用 does，其余用 do，过去时用 did。后面的动词一律用原形，不再变人称或时态。强调用法常见于肯定句和祈使句（Do come in!），也可用在疑问句中。","translate":"译成“确实……”“的确……”“一定要……”。中文用副词加重语气，不必把 do 单独译出来。","trap":{"wrong":"She does likes classical music.","right":"She does like classical music.","note":"强调用的 does 后面动词必须用原形，不能再加 -s，时态已经由 does 承担。"},"examples":[{"en":"I do believe this policy will benefit ordinary families.","zh":"我确实相信这项政策会让普通家庭受益。"},{"en":"He did warn us about the risk, but nobody listened.","zh":"他确实提醒过我们有风险，但没人听。"}],"understanding":"在动词原形前加 do/does/did 来强调肯定语气，意为“确实、的确”，时态和数由 do 体现。","translation":"译成“确实……”“的确……”“一定要……”。中文用副词加重语气，不必把 do 单独译出来。"},
{"key":"full-inversion","label":"完全倒装（Here comes… / On the table lies…）","definition":"把整个谓语动词放到主语前面叫完全倒装，多见于 here、there 或方位短语开头的句子。","identify":"句首是 here、there、now、then 或表示方位的介词短语，后面直接跟动词，主语出现在动词之后，形成“状语 + 动词 + 主语”的顺序。","usage":"结构：地点或方向状语 + 谓语动词 + 主语。谓语多为 come、go、lie、stand、sit、be 等不及物动词。主语是名词时倒装，主语是代词时不倒装：Here comes the bus，但 Here it comes。这类句子多用一般现在时。","translate":"译成“……来了”“……位于……”“……坐着……”。中文按正常语序说，不必保留倒装形式。","trap":{"wrong":"Here comes he.","right":"Here he comes.","note":"主语是代词时不倒装，代词 he 要放在动词 comes 前面，名词主语才后置。"},"examples":[{"en":"On the top of the hill stands an old temple.","zh":"山顶上矗立着一座古庙。"},{"en":"Here comes the train we have been waiting for.","zh":"我们一直在等的那趟火车来了。"}],"understanding":"把整个谓语动词放到主语前面叫完全倒装，多见于 here、there 或方位短语开头的句子。","translation":"译成“……来了”“……位于……”“……坐着……”。中文按正常语序说，不必保留倒装形式。"},
{"key":"not-until","label":"not … until 直到……才","definition":"not … until 表示某个动作到 until 所指的时间才发生，在那之前一直没有发生。","identify":"句中出现 not 或 never 与 until 搭配，until 后接时间点或从句，主句动作要到该时间之后才发生，之前一直没有发生。","usage":"结构：主语 + not + 谓语 + until + 时间。谓语是短暂动词时用一般过去时；强调“到那时才完成”可用过去完成时。It was not until … that … 是强调形式，that 后接正常语序；Not until 置于句首时主句部分倒装。","translate":"译成“直到……才……”。中文一定要有“才”，否则意思会变成“直到……都没有”。","trap":{"wrong":"Not until midnight he finished the essay.","right":"Not until midnight did he finish the essay.","note":"Not until 置于句首时，主句必须部分倒装，要补出助动词 did，实义动词用原形。"},"examples":[{"en":"I did not understand the rule until the teacher explained it.","zh":"直到老师讲解，我才弄懂这条规则。"},{"en":"It was not until 2019 that the two sides reached an agreement.","zh":"直到 2019 年双方才达成协议。"}],"understanding":"not … until 表示某个动作到 until 所指的时间才发生，在那之前一直没有发生。","translation":"译成“直到……才……”。中文一定要有“才”，否则意思会变成“直到……都没有”。"},
{"key":"subjunctive-inversion","label":"虚拟语气倒装（Were I … / Had I …）","definition":"虚拟条件句省略 if 时，把 were、had、should 提到主语前面形成倒装，意思不变。","identify":"句首直接是 Were I、Had he、Should it 等，后面没有 if，但整句仍在表达假设条件，就是虚拟语气倒装，多见于书面语。","usage":"规则：if 从句含 were、had、should 时，可去掉 if，把它们提到主语前：Were I you = If I were you；Had I known = If I had known；Should it rain = If it should rain。主句结构保持不变。从句谓语是其他实义动词的过去式时不能这样倒装。","translate":"译成“如果……”“要是……”。倒装不改变意思，补回 if 再理解最稳妥。","trap":{"wrong":"Was I you, I would accept the offer.","right":"Were I you, I would accept the offer.","note":"虚拟条件句的 be 动词一律用 were，倒装之后同样不能用 was，这是固定规则。"},"examples":[{"en":"Had I known the deadline, I would have started earlier.","zh":"要是我知道截止日期，就会早点开始。"},{"en":"Were the plan approved, construction would begin next spring.","zh":"如果方案获批，工程明年春天就会开工。"}],"understanding":"虚拟条件句省略 if 时，把 were、had、should 提到主语前面形成倒装，意思不变。","translation":"译成“如果……”“要是……”。倒装不改变意思，补回 if 再理解最稳妥。"},
{"key":"only-inversion","label":"Only + 介词短语 / 从句置于句首的部分倒装","definition":"only 加介词短语或状语从句放在句首时，主句要把助动词提到主语前，形成部分倒装。","identify":"句首是 Only + 介词短语、副词或从句，逗号后出现“助动词 + 主语 + 动词”，说明主句已经倒装。","usage":"结构：Only + 状语 + 助动词 + 主语 + 动词。only 修饰状语（by doing、then、when 从句）时主句倒装；only 修饰主语时不倒装，如 Only he knows the answer。原句没有助动词时要补 do/does/did，不能保留陈述语序。","translate":"译成“只有……才……”。only 引出的部分译成“只有”，主句译成“才”，语气要加重。","trap":{"wrong":"Only by practicing every day you can improve your pronunciation.","right":"Only by practicing every day can you improve your pronunciation.","note":"Only + 介词短语置于句首，主句要部分倒装，情态动词 can 提到主语前。"},"examples":[{"en":"Only when the data were rechecked did the error appear.","zh":"只有重新核对数据时，这个错误才显现出来。"},{"en":"Only in this way can we solve the problem quickly.","zh":"只有用这种方法，我们才能迅速解决问题。"}],"understanding":"only 加介词短语或状语从句放在句首时，主句要把助动词提到主语前，形成部分倒装。","translation":"译成“只有……才……”。only 引出的部分译成“只有”，主句译成“才”，语气要加重。"},
{"key":"wish-ifonly","label":"wish / if only / would rather 的虚拟表达","definition":"这三个词后面接不同时态，用来表达对现在或过去的遗憾，以及“宁愿”的愿望。","identify":"句中见到 wish、if only 或 would rather，后面动词不是正常时态，而是过去式或过去完成式，就是虚拟语气。","usage":"wish / if only + 过去式（be 用 were）表示与现在相反；+ had done 表示对过去的遗憾；+ would do 表示希望将来改变。would rather + 过去式表示现在或将来的宁愿；+ had done 表示对过去的宁愿。这些形式都不随人称变化。","translate":"wish 和 if only 译“真希望……”“要是……就好了”；would rather 译“宁愿……”。","trap":{"wrong":"I wish I have more time to read.","right":"I wish I had more time to read.","note":"wish 后表示与现在事实相反，要用过去式 had，不能用现在时 have，也没有 will 的说法。"},"examples":[{"en":"If only we had started the project earlier.","zh":"要是我们早点开始这个项目就好了。"},{"en":"I would rather you told me the truth directly.","zh":"我宁愿你直接告诉我真相。"},{"en":"She wishes she could speak French as fluently as her sister.","zh":"她希望自己法语能说得和姐姐一样流利。"}],"understanding":"这三个词后面接不同时态，用来表达对现在或过去的遗憾，以及“宁愿”的愿望。","translation":"wish 和 if only 译“真希望……”“要是……就好了”；would rather 译“宁愿……”。"},
{"key":"subjunctive","label":"虚拟语气（与事实相反 / 建议要求）","definition":"虚拟语气用特别的动词形式表达与事实相反的情况，或表示建议、要求、命令。","identify":"if 从句里用 were、had done、would have done，或 suggest、demand、essential 后接 (should) + 动词原形，都是虚拟语气的信号，要特别注意动词形式。","usage":"与现在相反：if + 过去式（be 用 were），主句用 would/could + 动词原形。与过去相反：if + had done，主句用 would have done。表示建议、要求、命令的词（suggest、insist、demand、It is necessary that）后，从句用 (should) + 动词原形，should 可省。","translate":"译成“如果……就……”“本来会……”“应该……”。与事实相反的要靠“本来、要是”点明。","trap":{"wrong":"If I was you, I would take the job.","right":"If I were you, I would take the job.","note":"虚拟条件句中 be 动词一律用 were，if I were you 是固定说法，口语里也很少用 was。"},"examples":[{"en":"If the team had prepared better, it would have won the match.","zh":"如果球队准备得更充分，本会赢下这场比赛。"},{"en":"The doctor insisted that the patient stay in bed for a week.","zh":"医生坚持让病人卧床一周。"}],"understanding":"虚拟语气用特别的动词形式表达与事实相反的情况，或表示建议、要求、命令。","translation":"译成“如果……就……”“本来会……”“应该……”。与事实相反的要靠“本来、要是”点明。"},
{"key":"but-for","label":"But for / Without 含蓄虚拟条件","definition":"but for 和 without 用介词短语代替 if 从句，表示“要不是……”，主句用虚拟形式。","identify":"句首出现 But for 或 Without + 名词，后面主句有 would/could/might have done 或 would do，就是含蓄的虚拟条件，主句不用 if 从句。","usage":"but for = without = 要不是、如果没有。指现在或将来，主句用 would/could + 动词原形；指过去，主句用 would/could have done。介词后面只接名词或动名词，不能接完整句子。but for 多用于书面语。","translate":"译成“要不是……”“如果没有……”。主句的“就……”要译出来，语气是假设。","trap":{"wrong":"But for you helped me, I would have failed.","right":"But for your help, I would have failed.","note":"but for 是介词短语，后面只能接名词或动名词，不能像 if 那样接完整的句子。"},"examples":[{"en":"But for the timely warning, the accident would have been worse.","zh":"要不是那场及时的预警，事故会更严重。"},{"en":"Without sufficient funding, the research would stop next year.","zh":"如果没有足够的资金，这项研究明年就会停止。"}],"understanding":"but for 和 without 用介词短语代替 if 从句，表示“要不是……”，主句用虚拟形式。","translation":"译成“要不是……”“如果没有……”。主句的“就……”要译出来，语气是假设。"},
{"key":"otherwise-subjunctive","label":"otherwise / or else + 虚拟语气（否则……）","definition":"otherwise 或 or else 引出与前面事实相反的结果，相当于“否则就……”，后面用虚拟形式。","identify":"前半句陈述事实，后半句以 otherwise、or、or else 开头，谓语是 would do 或 would have done，说明这是与事实相反的结果。","usage":"前句为真实情况，otherwise 后接虚拟结果：与过去相反用 would have done，与现在相反用 would do。or 和 or else 也表示“否则”，语气更口语。otherwise 前通常有逗号；放句首时也可能表示“在其他方面”。","translate":"译成“否则……”“不然就……”。中文用“否则、要不然”引出结果，虚拟语气不必另外标出。","trap":{"wrong":"I was busy yesterday; otherwise I would attend the meeting.","right":"I was busy yesterday; otherwise I would have attended the meeting.","note":"前句说的是过去的事实，otherwise 后的结果要用 would have done，不能用 would do，时态要跟事实对齐。"},"examples":[{"en":"The road was blocked; otherwise we would have arrived on time.","zh":"路被堵住了，否则我们会准时到达。"},{"en":"You should take notes, or else you will forget the details.","zh":"你应该记笔记，否则会忘掉细节。"}],"understanding":"otherwise 或 or else 引出与前面事实相反的结果，相当于“否则就……”，后面用虚拟形式。","translation":"译成“否则……”“不然就……”。中文用“否则、要不然”引出结果，虚拟语气不必另外标出。"},
{"key":"not-only-but-also","label":"not only … but also 递进并列","definition":"连接两个对等成分，表示后者比前者更进一步，句子的重点通常落在 but also 后面的内容上。","identify":"看到 not only 就找它后面的 A 和 but also 后面的 B；两者必须同为名词、动词、形容词或从句。","usage":"公式是 not only 加 A，再接 but also 加 B，A、B 必须同为名词、动词或从句，结构才对。not only 放到句首时，前半句要部分倒装：把助动词提到主语前面，没有助动词就借 do、does 或 did，实义动词用原形。","translate":"译成“不但……而且……”，中文重点放在后半句；倒装只是形式变化，不影响意思。","trap":{"wrong":"Not only she finished the task, but she also helped others.","right":"Not only did she finish the task, but she also helped others.","note":"not only 置于句首时前半句必须部分倒装，缺助动词要借 did，实义动词还原成原形。"},"examples":[{"en":"The new policy not only cut costs but also improved working conditions.","zh":"新政策不但降低了成本，而且改善了工作条件。"},{"en":"Not only does the course build vocabulary, but it also sharpens reading skills.","zh":"这门课不仅扩充词汇，还提升了阅读技巧。"}],"understanding":"连接两个对等成分，表示后者比前者更进一步，句子的重点通常落在 but also 后面的内容上。","translation":"译成“不但……而且……”，中文重点放在后半句；倒装只是形式变化，不影响意思。"},
{"key":"rather-than","label":"rather than / instead of 取舍对比","definition":"表示在两者中肯定前者、否定后者，核心是“是 A 而不是 B”的对比选择。","identify":"rather than 前后多为对等成分，常接动词原形；instead of 是介词短语，后面接名词或动名词。","usage":"rather than 连接两个对等成分，前后形式要一致；它放句首时，后面也接动词原形。instead of 是介词短语，后面接名词或动名词。判断时看空格后接什么：动词原形选 rather than，名词或动名词选 instead of。","translate":"译成“而不是／并非……”，肯定的内容放前面，用“而不是”引出被否定的部分。","trap":{"wrong":"He decided to walk rather than taking a taxi.","right":"He decided to walk rather than take a taxi.","note":"rather than 前后要对等，前面是动词原形 walk，后面也应用原形 take，不能接动名词。"},"examples":[{"en":"The committee blamed the delay on poor planning rather than on a lack of funds.","zh":"委员会把延误归咎于计划不周，而不是资金不足。"},{"en":"Instead of complaining about the noise, she moved to a quieter room.","zh":"她没有抱怨噪音，而是搬到了一个更安静的房间。"}],"understanding":"表示在两者中肯定前者、否定后者，核心是“是 A 而不是 B”的对比选择。","translation":"译成“而不是／并非……”，肯定的内容放前面，用“而不是”引出被否定的部分。"},
{"key":"ellipsis","label":"省略结构（if necessary / when asked / than expected）","definition":"状语从句和比较句里省掉与主句重复的主语和 be 动词，只留下关键词，使句子更简洁。","identify":"if、when、while、though、than 后面只剩形容词、分词或一个名词，没有完整的主谓结构，就是省略。","usage":"先补回被省掉的主语和 be：if necessary 补成 if it is necessary，when asked 补成 when he was asked。省掉的部分通常与主句主语一致；不一致时不能省，否则会形成垂悬结构。","translate":"译成“如果有必要／被问到时／比预期的……”，中文常补出主语或“情况”一词。","trap":{"wrong":"When asking about the plan, she gave no answer.","right":"When asked about the plan, she gave no answer.","note":"she 是“被问”的对象，应用过去分词 asked；用 asking 会变成“她去问别人”，逻辑主语错了。"},"examples":[{"en":"Students may leave early if necessary, but they must inform the teacher.","zh":"如果有必要，学生可以提前离开，但必须通知老师。"},{"en":"The results were better than expected in almost every category.","zh":"几乎在每个类别上，结果都比预期的好。"},{"en":"When asked about the delay, the manager refused to comment.","zh":"被问及延误时，经理拒绝置评。"}],"understanding":"状语从句和比较句里省掉与主句重复的主语和 be 动词，只留下关键词，使句子更简洁。","translation":"译成“如果有必要／被问到时／比预期的……”，中文常补出主语或“情况”一词。"},
{"key":"correlative","label":"关联连词 both … and / either … or / neither … nor","definition":"成对使用的连词，把两个对等成分连起来，分别表示“都”“二选一”“都不”。","identify":"看到 both、either、neither，就要在句中找对应的 and、or、nor，两部分必须是同类的词或短语，不能一边名词一边从句。","usage":"both A and B 表示两项都成立，谓语用复数；either A or B 表示二选一；neither A nor B 表示两项都不成立，本身已含否定。连接主语时，either … or 和 neither … nor 遵循就近原则。","translate":"分别译“既……又……”“要么……要么……”“既不……也不……”，不要漏掉 neither 的否定义。","trap":{"wrong":"Neither the data nor the method were reliable.","right":"Neither the data nor the method was reliable.","note":"neither … nor 连接主语时用就近原则，method 是单数，谓语用 was，不能用 were。"},"examples":[{"en":"The training is both practical and affordable for most small teams.","zh":"这项培训对多数小团队来说既实用又负担得起。"},{"en":"Either the manager or the assistants handle customer complaints every morning.","zh":"每天上午由经理或助手处理客户投诉。"},{"en":"Neither the price nor the quality attracted the buyers.","zh":"价格和质量都没能吸引买家。"}],"understanding":"成对使用的连词，把两个对等成分连起来，分别表示“都”“二选一”“都不”。","translation":"分别译“既……又……”“要么……要么……”“既不……也不……”，不要漏掉 neither 的否定义。"},
{"key":"semicolon-parallel","label":"分号并列句（; 连接两个完整分句）","definition":"用分号连接两个各自独立的完整分句，表示关系紧密的并列或对比，中间不用连词。","identify":"分号两边都必须有主语和谓语，能各自成句；分号后常跟 however、therefore、moreover 等连接副词。","usage":"写之前先确认分号两边都是完整句子，结构尽量对称。分号后如果用 however、therefore 这类连接副词，后面要加逗号。分号不能连接一个完整句和一个短语，也不能再和 but 同时使用。","translate":"中文可用“；”保留，也可拆成两句，或用“而、因此、然而”把两边的逻辑关系点出来。","trap":{"wrong":"The plan was cheap; but it took too long to carry out.","right":"The plan was cheap, but it took too long to carry out.","note":"分号本身已表示并列，不能再和 but 连用；要么用逗号加 but，要么改用 however。"},"examples":[{"en":"The first proposal was cheaper; the second was far more practical.","zh":"第一个方案更便宜；第二个方案实用得多。"},{"en":"The data were incomplete; therefore, the team delayed its conclusion.","zh":"数据不完整，因此团队推迟了结论。"}],"understanding":"用分号连接两个各自独立的完整分句，表示关系紧密的并列或对比，中间不用连词。","translation":"中文可用“；”保留，也可拆成两句，或用“而、因此、然而”把两边的逻辑关系点出来。"},
{"key":"colon-explain","label":"冒号解释与列举（: 后说明前文）","definition":"冒号用来引出对前文的解释、说明或列举，后面的内容具体回答“是什么、有哪些”。","identify":"冒号前通常是一个完整的分句，冒号后是名词短语、列表或完整句，用来具体展开前面的内容，而不是另起一个新话题。","usage":"冒号左边必须是完整句子，右边可以是名词短语、并列项或完整句。冒号后一般小写开头，除非是专有名词或完整句。不要把冒号和 such as 叠用，也不要在同一个句子里连用两个冒号。","translate":"译成“：”或“即、也就是”；列举时保留冒号，解释时也可以用“具体来说”。","trap":{"wrong":"The job requires skills such as: communication and teamwork.","right":"The job requires skills such as communication and teamwork.","note":"such as 后面直接接例子，不能再加冒号；冒号只能放在一个完整分句之后。"},"examples":[{"en":"The report reaches one conclusion: the current approach cannot be sustained.","zh":"报告得出一个结论：现行做法难以为继。"},{"en":"Three factors explain the decline: rising costs, weak demand, and poor management.","zh":"三个因素解释了这次下滑：成本上升、需求疲软和管理不善。"}],"understanding":"冒号用来引出对前文的解释、说明或列举，后面的内容具体回答“是什么、有哪些”。","translation":"译成“：”或“即、也就是”；列举时保留冒号，解释时也可以用“具体来说”。"},
{"key":"not-but","label":"not … but … 不是……而是……","definition":"否定前者、肯定后者的并列结构，重点在 but 后面的内容，前后成分必须对等。","identify":"句中出现 not A but B，A 和 B 是同类成分；not 后面也可能跟 because、only 等词构成变体。","usage":"公式是 not 加 A，再加 but 加 B，A、B 形式要一致：名词配名词，从句配从句。not 只否定 A，but 后面的 B 才是重心，谓语随 B 走。它和 not only … but also … 不同：前者否定 A，后者肯定两者。","translate":"译成“不是……而是……”，把 but 后的内容作为重点，不要译成“不但……而且……”。","trap":{"wrong":"The problem is not the cost, but because of the delay.","right":"The problem is not the cost but the delay.","note":"not 和 but 后面必须对等，前面是名词 cost，后面也应是名词 delay，不能换成 because 从句。"},"examples":[{"en":"Success depends not on luck but on consistent effort.","zh":"成功靠的不是运气，而是持续的努力。"},{"en":"What she wanted was not sympathy but a chance to prove herself.","zh":"她想要的不是同情，而是一个证明自己的机会。"}],"understanding":"否定前者、肯定后者的并列结构，重点在 but 后面的内容，前后成分必须对等。","translation":"译成“不是……而是……”，把 but 后的内容作为重点，不要译成“不但……而且……”。"},
{"key":"coordination","label":"并列句与并列成分（and / but / or / so）","definition":"用 and、but、or、so 等并列连词连接两个对等成分或两个独立分句，两者地位平等。","identify":"看到 and、but、or、so、for、yet 连接的两部分，先判断它们是短语还是完整分句，再看结构是否对等。","usage":"连接两个完整分句时，连词前加逗号；连接词或短语时不用逗号。and 表添加，but 表转折，or 表选择或否则，so 表结果，for 表原因。三个以上并列项写成 A、B and C，最后一项前加 and。","translate":"and 译“并且、和”，but 译“但是”，or 译“或者、否则”，so 译“所以”，for 译“因为”。","trap":{"wrong":"Although the sample was small, so the results may not be reliable.","right":"The sample was small, so the results may not be reliable.","note":"although 和 so 不能同时使用，让步和结果只能选一个连词，否则句子逻辑打架。"},"examples":[{"en":"The weather was terrible, but the team finished the survey on time.","zh":"天气很糟糕，但团队按时完成了调查。"},{"en":"You can submit the form online or hand it in at the office.","zh":"你可以在线提交表格，也可以交到办公室。"}],"understanding":"用 and、but、or、so 等并列连词连接两个对等成分或两个独立分句，两者地位平等。","translation":"and 译“并且、和”，but 译“但是”，or 译“或者、否则”，so 译“所以”，for 译“因为”。"},
{"key":"elliptical-clause","label":"省略结构（if necessary / when possible）","definition":"并列句或从句中省掉重复的谓语部分，避免啰嗦，省略后留下的成分仍能对应补全。","identify":"并列句后半段只剩助动词、do/does/did 或一个名词，或者从句只剩 when possible 这类短语，就是省略。","usage":"补全办法是把前半句的谓语或主语搬过来：前半句说他喜欢茶，后半句只剩她咖啡，就要补出同样的动词；遇到 when possible，就补成 when it is possible。补全后要保证两边结构对等、意思通顺。","translate":"中文往往要把省略的动词或主语补出来，读起来才自然；不要照英文硬省。","trap":{"wrong":"He didn't attend the meeting, but she did attended.","right":"He didn't attend the meeting, but she did attend.","note":"did 已经承担了过去时，后面必须接动词原形 attend，不能再接过去式 attended。"},"examples":[{"en":"He prefers tea in the morning and she coffee after lunch.","zh":"他早上喜欢喝茶，她午饭后喜欢喝咖啡。"},{"en":"The manager can approve the budget, and so can his deputy.","zh":"经理能批准这笔预算，他的副手也能。"},{"en":"Some students finished the assignment early; others will do so by Friday.","zh":"有些学生提前完成了作业，其他人会在周五前完成。"}],"understanding":"并列句或从句中省掉重复的谓语部分，避免啰嗦，省略后留下的成分仍能对应补全。","translation":"中文往往要把省略的动词或主语补出来，读起来才自然；不要照英文硬省。"},
{"key":"substitution","label":"替代（do so / one / that / so）","definition":"替代是用一个短词顶替前面出现过的内容，避免重复；英语里常用 do so、one/ones、that/those、so 四种形式。","identify":"看替代词替代的是什么：do so 替代动作或动词短语；one/ones 替代可数名词；that/those 替代前面提到的名词，后面常带 of/in 等修饰；so 替代整个从句或形容词。","usage":"do so 代替动词短语，如 He asked me to leave and I did so；one/ones 代替可数名词，前面常有形容词，如 a red one；that/those 代替前面提到的名词，常带 of/in 等后置修饰，如 the climate of Japan is milder than that of Korea；so 代替整个从句，如 I think so，也可代替形容词，如 so is she。先判断被替代的是动作、名词还是从句，再选替代词，就不会混用。","translate":"中文一般不译出替代词，直接用“这样/也一样/那个”带过；that/those 常译成“的”字结构，如“韩国的（气候）”。","trap":{"wrong":"The population of China is larger than one of India.","right":"The population of China is larger than that of India.","note":"这里替代的是不可数的 population，不能用 one；替代前面带 of 修饰的名词要用 that，单数用 that，复数用 those。"},"examples":[{"en":"He promised to call me back, but he never did so.","zh":"他答应给我回电话，却从没这样做。"},{"en":"I do not like this dictionary; please show me a smaller one.","zh":"我不喜欢这本词典，请给我拿一本小一点的。"},{"en":"The rules of this game are simpler than those of chess.","zh":"这个游戏的规则比国际象棋的规则简单。"}],"understanding":"替代是用一个短词顶替前面出现过的内容，避免重复；英语里常用 do so、one/ones、that/those、so 四种形式。","translation":"中文一般不译出替代词，直接用“这样/也一样/那个”带过；that/those 常译成“的”字结构，如“韩国的（气候）”。"},
{"key":"there-be","label":"there be 存在句（含 there is evidence that）","definition":"表示某处存在某人或某物，there 只是引导词，真正的主语是 be 后面的名词。","identify":"句首出现 there be 形式，后面跟名词；也可能有 there was 或 there is evidence that 等变体。","usage":"谓语单复数看后面名词：单数用 is，复数用 are。there be 不能和 have 混用：首次提及用 there be，所属关系用 have。there is evidence that 中 that 从句说明 evidence 内容。","translate":"译成“有……／存在……”，there 不译“那里”；there is evidence that 译“有证据表明……”。","trap":{"wrong":"There have many reasons for the change.","right":"There are many reasons for the change.","note":"there be 句型用 be 动词，不能用 have；真正的主语是 many reasons，所以用 are。"},"examples":[{"en":"There is a growing gap between urban and rural incomes.","zh":"城乡收入差距正在扩大。"},{"en":"There are strong reasons to doubt the accuracy of the report.","zh":"有充分理由怀疑这份报告的准确性。"},{"en":"There is evidence that regular exercise improves mental health.","zh":"有证据表明经常锻炼能改善心理健康。"}],"understanding":"表示某处存在某人或某物，there 只是引导词，真正的主语是 be 后面的名词。","translation":"译成“有……／存在……”，there 不译“那里”；there is evidence that 译“有证据表明……”。"},
{"key":"partial-negation","label":"部分否定与否定转移（all … not / not … because）","definition":"not 与 all、both、every 连用只否定一部分，意思是“并非全部都……”，不是全部否定。","identify":"看到 all、both、every、always 与 not 同句，或 not 后紧跟 because，就要警惕部分否定和否定转移。","usage":"all … not 表示并非所有都；both … not 表示并非两个都；every … not 表示并非每个都。全部否定要用 none、neither、no one。not … because 常把否定移到从句，要按逻辑判断否定的对象。","translate":"all … not 译“并非所有……都”；not … because 按逻辑译“不是因为……”；不能一律译成“全都不”。","trap":{"wrong":"Both of the answers are not correct.","right":"Neither of the answers is correct.","note":"both … not 是部分否定，意为“并非两个都对”；要表达“两个都不对”必须用 neither。"},"examples":[{"en":"Not every solution works equally well for every patient.","zh":"并非每种疗法对每位患者都同样有效。"},{"en":"She did not marry him because he was rich.","zh":"她嫁给他并不是因为他有钱。"},{"en":"Not all the data were collected in the same way.","zh":"并非所有数据都是以同样的方式收集的。"}],"understanding":"not 与 all、both、every 连用只否定一部分，意思是“并非全部都……”，不是全部否定。","translation":"all … not 译“并非所有……都”；not … because 按逻辑译“不是因为……”；不能一律译成“全都不”。"},
{"key":"double-negative","label":"双重否定（not uncommon / never … without）","definition":"句中出现两个否定形式，合起来表达肯定的意思，语气通常比直接肯定更强。","identify":"看到 not 与 uncommon、unlikely、without、never、no 等否定词同句出现，就是双重否定。","usage":"not uncommon 表示很常见，not unusual 表示不少见；never … without 表示每次……都……；no … without 表示没有……就没有……；cannot … too 表示再……也不为过。翻译时改译肯定句。","translate":"译成肯定句：“很常见／每次……都……／没有……就没有……”，可加“难免、无不”保留语气。","trap":{"wrong":"It is not uncommon that students don't feel anxious before exams.","right":"It is not uncommon for students to feel anxious before exams.","note":"not uncommon 已表示“常见”，从句再用 don't 会变成“不焦虑很常见”，否定叠加导致意思相反。"},"examples":[{"en":"It is not unusual for new employees to make mistakes in the first month.","zh":"新员工在第一个月犯错并不少见。"},{"en":"She never visits the city without stopping by her old school.","zh":"她每次去那座城市都会去看看母校。"}],"understanding":"句中出现两个否定形式，合起来表达肯定的意思，语气通常比直接肯定更强。","translation":"译成肯定句：“很常见／每次……都……／没有……就没有……”，可加“难免、无不”保留语气。"},
{"key":"exclamatory","label":"感叹句（What / How）","definition":"用 what 或 how 引出感叹，表达强烈情绪；what 修饰名词，how 修饰形容词或副词。","identify":"句首是 What 或 How，句末用感叹号，且没有疑问对象，就是感叹句；再看 What 后有没有名词。","usage":"公式：What 加形容词加名词，再加主语和谓语；How 加形容词或副词，再加主语和谓语。单数可数名词前别忘了 a 或 an，不可数名词和复数名词不加。How 后面不能直接跟名词。","translate":"译成“多么……啊／真……”，中文常把“多么”放句首，句末加语气词。","trap":{"wrong":"What a beautiful weather it is!","right":"What beautiful weather it is!","note":"weather 是不可数名词，不能加 a；What 后接不可数名词时直接用形容词加名词。"},"examples":[{"en":"What a remarkable change the policy has brought to the village!","zh":"这项政策给村子带来了多么巨大的变化啊！"},{"en":"How quickly the technology has developed over the past decade!","zh":"过去十年里这项技术发展得多么快啊！"}],"understanding":"用 what 或 how 引出感叹，表达强烈情绪；what 修饰名词，how 修饰形容词或副词。","translation":"译成“多么……啊／真……”，中文常把“多么”放句首，句末加语气词。"},
{"key":"tag-question","label":"反意疑问句（…, isn't it?）","definition":"陈述句后加一个简短问句，用来确认或寻求认同；前后肯定否定相反，主语用人称代词。","identify":"句子由“陈述句 + 逗号 + 助动词 + 代词”构成，句末是问号；前肯后否，前否后肯。","usage":"分三步：一，前句肯定则后句否定，反之亦然；二，后句助动词与前句的时态、情态一致，没有就借 do/does/did；三，主语换成对应的人称代词。含 never、hardly、little 的句子算否定，后句要用肯定形式。","translate":"译成“……不是吗／对吧／好不好”，语气不必太重，常带确认或寻求认同的意味。","trap":{"wrong":"She has finished the report, doesn't she?","right":"She has finished the report, hasn't she?","note":"后句助动词要与前句的 has 一致，不能换成 doesn't；时态由前句决定。"},"examples":[{"en":"The meeting starts at nine tomorrow, doesn't it?","zh":"会议明天九点开始，对吧？"},{"en":"You have never been to that museum, have you?","zh":"你从没去过那家博物馆，对吧？"},{"en":"Let's take a short break before we continue, shall we?","zh":"我们休息一下再继续，好吗？"}],"understanding":"陈述句后加一个简短问句，用来确认或寻求认同；前后肯定否定相反，主语用人称代词。","translation":"译成“……不是吗／对吧／好不好”，语气不必太重，常带确认或寻求认同的意味。"},
{"key":"indirect-speech","label":"间接引语（said / told / asked + 从句）","definition":"转述别人的话，把直接引语的时态、人称和时间状语按转述时刻作相应调整。","identify":"看到 said、told、asked 后接 that、whether、if 或疑问词引导的从句，就是间接引语。","usage":"主句是过去时，从句时态往后退一步：现在变过去，过去变过去完成，将来变 would。人称按转述者调整，时间地点词也要变，如 now 变 then、today 变 that day。said 后面不加人，told 必须加人；疑问句用陈述语序。","translate":"译成“……说／问……”，中文时态不必后移，但“今天、这里”等要按语境换。","trap":{"wrong":"He asked me where did I live.","right":"He asked me where I lived.","note":"间接引语里的疑问从句要用陈述语序，不能保留 did 提前的疑问语序。"},"examples":[{"en":"She told me that she would send the file the next day.","zh":"她告诉我她第二天会把文件发过来。"},{"en":"The teacher asked whether we had understood the main idea.","zh":"老师问我们是否理解了主旨。"}],"understanding":"转述别人的话，把直接引语的时态、人称和时间状语按转述时刻作相应调整。","translation":"译成“……说／问……”，中文时态不必后移，但“今天、这里”等要按语境换。"},
{"key":"fronted-adverbial","label":"句首状语前置（In … / For … / At …）","definition":"把时间、地点、原因等状语放到句首，用来交代背景或衔接上文，主句仍用正常语序。","identify":"句首是 In、For、At、During、With 等介词短语或副词短语，后面紧跟完整的主谓结构，就是状语前置。","usage":"时间、原因、条件状语前置通常加逗号，主句不倒装。地点状语放句首时一般也不倒装，只有 here、there 或 on the wall 这类方位短语引出时才是完全倒装。翻译时先译状语，再译主句；状语太长时放句首能平衡句子。","translate":"译成“在……／为了……／由于……”，中文习惯把状语放句首，正好与英文对应。","trap":{"wrong":"In the past decade has seen rapid growth in online education.","right":"The past decade has seen rapid growth in online education.","note":"In the past decade 是时间状语，不能作主语；去掉 In，the past decade 才能作主语。"},"examples":[{"en":"In the past five years, the city has doubled its green space.","zh":"过去五年里，这座城市的绿地面积翻了一番。"},{"en":"For many students, part-time work offers both income and experience.","zh":"对许多学生来说，兼职既带来收入也带来经验。"},{"en":"At the beginning of the term, the teacher explained the assessment rules.","zh":"学期初，老师说明了考核规则。"}],"understanding":"把时间、地点、原因等状语放到句首，用来交代背景或衔接上文，主句仍用正常语序。","translation":"译成“在……／为了……／由于……”，中文习惯把状语放句首，正好与英文对应。"},
{"key":"object-complement","label":"宾语补足语（make / find / consider + 宾语 + 形容词 / 名词）","definition":"放在宾语后面，补充说明宾语的状态、身份或特征，与宾语构成逻辑上的主谓关系。","identify":"make、find、consider、keep、call、elect 等动词后，宾语后面跟形容词或名词，能改写成宾语加 be，就是宾补。","usage":"常见搭配：make 加宾语加形容词，find 加宾语加形容词，consider 加宾语加名词或形容词，elect 和 call 加宾语加名词。判断办法是在宾语和补语之间加 be，意思通顺就是宾补。it 作形式宾语时，补语放在 it 后面。","translate":"译成“使……变得……／认为……是……／发现……很……”，补语按中文习惯放在后面。","trap":{"wrong":"The news made him happily.","right":"The news made him happy.","note":"make + 宾语 + 形容词作宾补，不能用副词 happily；这里描述 him 的状态，要用形容词。"},"examples":[{"en":"The new evidence made the conclusion far more convincing.","zh":"新证据使这个结论更有说服力。"},{"en":"Many critics consider the novel a masterpiece of its era.","zh":"许多评论家认为这部小说是那个时代的杰作。"},{"en":"We found the instructions rather difficult to follow.","zh":"我们发现这些说明很难照着做。"}],"understanding":"放在宾语后面，补充说明宾语的状态、身份或特征，与宾语构成逻辑上的主谓关系。","translation":"译成“使……变得……／认为……是……／发现……很……”，补语按中文习惯放在后面。"},
{"key":"with-absolute","label":"with 复合结构（独立主格）","definition":"with + 名词 + 分词、形容词或介词短语，表示伴随、原因或条件，相当于一个状语从句。","identify":"看到 with 后面先跟一个名词，再接 -ing、-ed、形容词或介词短语，且这个名词不是主句主语，就是 with 复合结构。","usage":"名词和后面的分词构成逻辑主谓关系：主动、进行用 -ing（with the rain falling），被动、完成用 -ed（with the work finished）。它常作伴随或原因状语，可放在句首或句尾，翻译时通常拆成一个分句。","translate":"译成“随着……／在……的情况下／……着”，不要一律译成“和……一起”。","trap":{"wrong":"With the exam approached, students became nervous.","right":"With the exam approaching, students became nervous.","note":"exam 与 approach 是主动关系，应用现在分词 approaching；approached 含被动义。"},"examples":[{"en":"With the deadline approaching, the team worked through the weekend.","zh":"随着截止日期临近，团队整个周末都在工作。"},{"en":"She sat by the window with her eyes fixed on the distant hills.","zh":"她坐在窗边，目光凝视着远处的山丘。"}],"understanding":"with + 名词 + 分词、形容词或介词短语，表示伴随、原因或条件，相当于一个状语从句。","translation":"译成“随着……／在……的情况下／……着”，不要一律译成“和……一起”。"},
{"key":"absolute-noun","label":"独立主格（名词 + 分词，无 with）","definition":"不带 with 的“名词 + 分词或形容词”结构，前面的名词是后面分词的逻辑主语，整体作状语。","identify":"句首或句中有一段“名词 + -ing/-ed/形容词”，名词不是主句的主语或宾语，且没有连词和 be 动词。","usage":"主动关系用现在分词，如“天气允许”；被动关系用过去分词，如“工作完成”。它相当于一个状语从句，可表时间、原因、条件或伴随。注意它不能单独成句，也不能再加 and 或谓语。","translate":"译成“由于……／……之后／如果……”，先译这个小结构，再译主句。","trap":{"wrong":"The work finishing, they went home.","right":"The work finished, they went home.","note":"work 是被完成的，用过去分词 finished 表示被动完成；finishing 会变成“工作自己完成”。"},"examples":[{"en":"Weather permitting, the ceremony will be held in the garden.","zh":"如果天气允许，仪式将在花园举行。"},{"en":"His health failing, he gave up the demanding job.","zh":"由于健康状况恶化，他辞去了这份高强度的工作。"}],"understanding":"不带 with 的“名词 + 分词或形容词”结构，前面的名词是后面分词的逻辑主语，整体作状语。","translation":"译成“由于……／……之后／如果……”，先译这个小结构，再译主句。"},
{"key":"nested-clauses","label":"多层从句嵌套","definition":"一个句子里从句套从句，包含两个以上引导词，需要分层找出各自修饰的成分。","identify":"句中出现两个以上 that、which、who、when、because、although 等引导词，或一个从句里又出现主谓，就是嵌套。","usage":"先找最外层主句的主语和谓语，把从句暂时括起来；再从每个引导词出发，看它修饰哪个名词或说明哪个成分；最后逐层还原。不要按英文顺序逐词翻译，先译主干，再把每层修饰按中文习惯放回。","translate":"按“先主干、后修饰”来译：先译主句骨架，再把各层从句拆成短句，用“这、其、因为”衔接。","trap":{"wrong":"The study that shows people who read regularly are smarter.","right":"The study shows that people who read regularly are smarter.","note":"第一个 that 被误当成定语从句引导词，导致主句没有谓语；这里 that 引导宾语从句，主句谓语是 shows。"},"examples":[{"en":"Researchers found that children who read daily develop stronger language skills than those who rarely read.","zh":"研究者发现，每天阅读的儿童比很少阅读的儿童语言能力更强。"},{"en":"The report argues that the policy failed because the people who designed it ignored local conditions.","zh":"报告认为，该政策失败是因为设计者忽视了当地条件。"}],"understanding":"一个句子里从句套从句，包含两个以上引导词，需要分层找出各自修饰的成分。","translation":"按“先主干、后修饰”来译：先译主句骨架，再把各层从句拆成短句，用“这、其、因为”衔接。"},
{"key":"long-sentence","label":"长句拆解（主干 + 修饰）","definition":"把长句按主干、修饰和插入成分切块，先抓住谁做了什么，再逐块还原细节。","identify":"句子超过三十词、逗号多、从句和介词短语层层叠加，一眼找不到主谓，就需要按块拆解。","usage":"四步：一，划掉插入语和括号；二，找出主句的主语和谓语；三，把每个从句和介词短语挂到它修饰的词上；四，按中文“先条件、后结果”的顺序重新排列。拆完再合，不要逐词硬译。","translate":"先译主干，再把修饰成分拆成短句，用“这、因此、由于”连接，避免一句到底。","trap":{"wrong":"The report which was published last week and it claims that the policy failed.","right":"The report, which was published last week, claims that the policy failed.","note":"which 从句已经占用了谓语位置，主句还需要真正的谓语 claims；and it 会造成两个主语并列。"},"examples":[{"en":"Although the results were encouraging, the researchers warned that the sample was too small to support firm conclusions.","zh":"尽管结果令人鼓舞，研究者仍警告说样本太小，无法支撑确定的结论。"},{"en":"The company that once dominated the market now struggles to adapt to changes that few people predicted.","zh":"曾经主导市场的这家公司，如今难以适应很少有人预料到的变化。"}],"understanding":"把长句按主干、修饰和插入成分切块，先抓住谁做了什么，再逐块还原细节。","translation":"先译主干，再把修饰成分拆成短句，用“这、因此、由于”连接，避免一句到底。"},
{"key":"long-insertion","label":"长句结构：插入语与分隔","definition":"插入语是插在句子中间、用逗号或破折号隔开的成分，它不充当句子成分，删掉后句子依然完整。","identify":"长句里看到两个逗号、两个破折号或一对括号夹住的一小段，先判断它是不是插入语；常见信号是 however、therefore、for example、in fact、I think、as a result。","usage":"三步拆：①把插入语整体括起来先跳过，主句的主谓立刻显形；②判断插入语的作用，是转折、举例、补充还是说话人态度；③再把插入语放回中文的句首或分句位置。注意插入语常把主谓或动宾隔开，别把被隔开的两半当成两个成分。","translate":"插入语按功能译到句首：“然而/因此/例如/事实上/我认为”，不要卡在原位置；破折号里的内容可译成括号或独立短句。","trap":{"wrong":"The plan, I think, it will take too long.","right":"The plan, I think, will take too long.","note":"插入语 I think 不占句子成分，删掉也成立；主句主语 the plan 之后直接接谓语 will take，不能再加一个 it 作主语。"},"examples":[{"en":"The new policy, however, will not affect small businesses.","zh":"然而，新政策不会影响小企业。"},{"en":"Many students, especially those in rural areas, lack reliable internet access.","zh":"许多学生，尤其是农村地区的学生，缺乏稳定的网络。"},{"en":"The data, collected over ten years, suggest a clear downward trend.","zh":"这些数据采集了十年，显示出明显的下降趋势。"}],"understanding":"插入语是插在句子中间、用逗号或破折号隔开的成分，它不充当句子成分，删掉后句子依然完整。","translation":"插入语按功能译到句首：“然而/因此/例如/事实上/我认为”，不要卡在原位置；破折号里的内容可译成括号或独立短句。"},
{"key":"long-inversion","label":"长句结构：倒装与前置","definition":"倒装是把谓语或助动词提到主语前面；前置是把状语、表语等本来不居首的成分放到句首。","identify":"句首出现否定词（not、never、hardly、seldom、little）、only 加状语、so/such ... that 或地点状语，而主谓顺序反常，就是倒装；先找助动词，再找真正的主语，语序还原后意思就清楚了。","usage":"拆解步骤：①确认句首成分是否触发倒装；②把助动词、be 或情态动词放回主语后面，还原正常语序；③分清部分倒装和完全倒装，后者多见于 here/there 或地点状语加 be/come/lie。not until 放句首时，倒装发生在主句，不是 until 从句。","translate":"按还原后的正常语序译：Not until ... did ... 译“直到……才……”；Only by ... can ... 译“只有……才……”；Never ... 译“从不……”，不要照搬倒装语序，前置成分只是强调，不影响句子主干。","trap":{"wrong":"Not until he left did I realized how much I owed him.","right":"Not until he left did I realize how much I owed him.","note":"did 已经承担了过去时，后面的实义动词必须用原形 realize，不能再加 -ed，这是倒装句最常见的错。"},"examples":[{"en":"Only when the results were published did the public learn the truth.","zh":"直到结果公布，公众才得知真相。"},{"en":"Seldom has the committee faced such a difficult decision.","zh":"委员会很少面对如此艰难的决定。"},{"en":"On the table lay a stack of letters nobody had opened.","zh":"桌上放着一叠没人拆开过的信。"}],"understanding":"倒装是把谓语或助动词提到主语前面；前置是把状语、表语等本来不居首的成分放到句首。","translation":"按还原后的正常语序译：Not until ... did ... 译“直到……才……”；Only by ... can ... 译“只有……才……”；Never ... 译“从不……”，不要照搬倒装语序，前置成分只是强调，不影响句子主干。"},
{"key":"long-ellipsis","label":"长句结构：省略与替代","definition":"省略是把重复或可推知的成分删掉，替代是用 do/one/that/so 等短词顶替，两者都让长句更紧凑。","identify":"长句里出现“缺主语或缺谓语”却读得通，或出现 do/did/one/that/so 指代前文，就是省略或替代；常见于状语从句、比较结构和并列句。","usage":"拆解步骤：①先找完整的主谓，看哪里缺了；②按语法补回被省的成分，多为“主语 + be”；③把替代词还原成前文的内容再理解。比较句 than 后、状语从句 when/while/if 后、并列句第二分句，是省略最集中的三个位置。","translate":"被省的部分中文常常要补出来才通顺：“如果有必要/被问到时/比预期更……”；替代词不必译，但要把它指代的内容说清楚。","trap":{"wrong":"When asking about the delay, he said nothing.","right":"When asked about the delay, he said nothing.","note":"when 从句省略了 he was，主语 he 是被问的人，必须用被动 asked，不能用主动 asking，否则逻辑主语就错了。"},"examples":[{"en":"The results were better than expected, although some data were missing.","zh":"尽管缺少一些数据，结果还是比预期的好。"},{"en":"She can speak French, and her brother can too.","zh":"她会说法语，她弟弟也会。"},{"en":"If necessary, the meeting will be moved online.","zh":"如果有必要，会议将改到线上举行。"}],"understanding":"省略是把重复或可推知的成分删掉，替代是用 do/one/that/so 等短词顶替，两者都让长句更紧凑。","translation":"被省的部分中文常常要补出来才通顺：“如果有必要/被问到时/比预期更……”；替代词不必译，但要把它指代的内容说清楚。"},
{"key":"long-parallel","label":"长句结构：并列与对比","definition":"并列是把结构相同、地位对等的成分用 and/but/or 等连起来；对比是并列中带有相反或对照关系。","identify":"看到 and、but、or、not only ... but also、rather than、while、whereas 先找它连接的两端；两端词性或结构必须一致，长句里常被修饰语拉得很远，先跳过中间部分直接看两端。","usage":"拆解步骤：①圈出并列连词，确定它连的是词、短语还是分句；②把连词两边对齐，检查结构是否平行；③遇到 not only ... but also、either ... or、neither ... nor，第二部分要和第一部分形式一致。长句里先跳过中间修饰语，直接找连词两端。","translate":"and 译“和/并且”，but 译“但是”，while/whereas 表对比时译“而/相比之下”，rather than 译“而不是”；中文可重复动词让对比更清楚。","trap":{"wrong":"She likes reading, swimming and to paint.","right":"She likes reading, swimming and painting.","note":"and 连接的并列成分要形式一致，前面是动名词 reading、swimming，后面也必须用动名词 painting，不能换成不定式。"},"examples":[{"en":"The report is not only longer than the previous one but also far more detailed.","zh":"这份报告不仅比上一份长，而且详细得多。"},{"en":"Some countries rely on coal, whereas others have shifted to wind and solar power.","zh":"有些国家依赖煤炭，而另一些国家已转向风能和太阳能。"},{"en":"He chose to resign rather than accept the unfair terms.","zh":"他选择辞职，而不是接受不公平的条款。"}],"understanding":"并列是把结构相同、地位对等的成分用 and/but/or 等连起来；对比是并列中带有相反或对照关系。","translation":"and 译“和/并且”，but 译“但是”，while/whereas 表对比时译“而/相比之下”，rather than 译“而不是”；中文可重复动词让对比更清楚。"},
{"key":"long-postmodifier","label":"长句结构：后置修饰叠加","definition":"后置修饰是放在名词后面修饰它的成分，如介词短语、分词短语、定语从句；叠加就是好几个接连跟在一个名词后。","identify":"长句里名词后面连着出现 of/in 介词短语、doing/done 分词、who/which/that 从句，就是后置修饰叠加；先找到名词，再判断每一层修饰到哪里结束。","usage":"拆解步骤：①先锁定中心名词；②把每个后置修饰单独切开，判断它修饰中心名词还是修饰前一个修饰语；③按“由近到远”往里剥，离名词最近的修饰关系最紧。遇到连串 of 短语时从最后一个 of 往前读，再套定语从句就不会乱。","translate":"中文把修饰成分前置成“的”字结构，按从远到近排列，如 the number of students who ... 译“……的学生的数量”；太长时拆成短句另说。","trap":{"wrong":"The number of students who studies abroad has risen.","right":"The number of students who study abroad has risen.","note":"定语从句的谓语跟先行词 students 一致，用复数 study；主句谓语才跟 the number 用单数 has，两个主语别混。"},"examples":[{"en":"The number of people who work from home has increased sharply in recent years.","zh":"近年来居家办公的人数急剧增加。"},{"en":"The proposal put forward by the committee at yesterday's meeting was rejected.","zh":"委员会在昨天会上提出的建议被否决了。"},{"en":"The idea that machines might replace teachers worries many parents.","zh":"机器可能取代老师的想法让许多家长担忧。"}],"understanding":"后置修饰是放在名词后面修饰它的成分，如介词短语、分词短语、定语从句；叠加就是好几个接连跟在一个名词后。","translation":"中文把修饰成分前置成“的”字结构，按从远到近排列，如 the number of students who ... 译“……的学生的数量”；太长时拆成短句另说。"}
]
